            setConnectionConfig(parsedConfig);
            setApiKey(parsedConfig.apiKey);
            setRegion(parsedConfig.region);
            setModel(parsedConfig.model);
            setShowDeploymentGuide(false); // Hide guide if config is present
          }
        }, []);

        useEffect(() => {
          if (apiKey && region) {
            getModels(apiKey, region)
              .then(data => {
                setModels(data);
              })
              .catch(err => {
                console.error('Error fetching models:', err);
                setError('Failed to fetch models. Check your API key and region.');
              });
          }
        }, [apiKey, region]);

        const handleApiKeyChange = (e) => {
          setApiKey(e.target.value);
        };

        const handleRegionChange = (e) => {
          setRegion(e.target.value);
        };

        const handleModelChange = (e) => {
          setModel(e.target.value);
        };

        const handleSaveConfig = () => {
          const config = { apiKey, region, model };
          setConnectionConfig(config);
          localStorage.setItem('vertex_config', JSON.stringify(config));
          setShowDeploymentGuide(false);
          alert('Configuration saved to browser storage!'); // Replace with a more elegant UI element
        };

        const handleGenerate = async (prompt, model) => {
          if (!apiKey || !region || !model) {
            setError('Please configure your API key, region, and model before generating.');
            setShowDeploymentGuide(true);
            return;
          }
          setIsLoading(true);
          setError(null);
          setVideoBlob(null);

          try {
            const videoBlob = await generateVideo(apiKey, region, model, prompt);
            setVideoBlob(videoBlob);
            setShowDeploymentGuide(false); // Hide guide after successful generation
          } catch (err) {
            console.error('Video generation error:', err);
            if (err.message.includes('404')) {
              setError('Model not found. Please verify your model in Model Garden.');
            } else {
              setError(`Video generation failed: ${err.message}`);
            }
            setShowDeploymentGuide(true);
          } finally {
            setIsLoading(false);
          }
        };

        return (
          <div className="App">
            <header className="App-header">
              <h1>VIDEO_ZAVOD</h1>
            </header>
            {error && <div className="error-message">{error}</div>}
            <PromptForm onGenerate={handleGenerate}
                        apiKey={apiKey}
                        region={region}
                        model={model}
                        onApiKeyChange={handleApiKeyChange}
                        onRegionChange={handleRegionChange}
                        on

