import {Video} from '@google/genai';
import React, {useCallback, useEffect, useState} from 'react';
import LoadingIndicator from './components/LoadingIndicator';
import PromptForm from './components/PromptForm';
import VideoResult from './components/VideoResult';
import ApiKeyDialog from './components/ApiKeyDialog';
import DiagnosticsModal from './components/DiagnosticsModal';
import DeploymentGuideModal from './components/DeploymentGuideModal';
import {generateVideo} from './services/geminiService';
import {PlusIcon, WalletIcon, ActivityIcon, ServerIcon} from './components/icons';
import {
  AppState,
  AspectRatio,
  GenerateVideoParams,
  GenerationMode,
  Resolution,
  VideoFile,
  VertexConnectionConfig,
} from './types';

declare global {
  interface AIStudio {
    hasSelectedApiKey: () => Promise<boolean>;
    openSelectKey: () => Promise<void>;
  }
}

const STORAGE_KEY = 'video_zavod_vertex_config';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.IDLE);
  const [videoUrl, setVideoUrl] = useState<string | null>(null);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [lastConfig, setLastConfig] = useState<GenerateVideoParams | null>(
    null,
  );
  const [lastVideoObject, setLastVideoObject] = useState<Video | null>(null);
  const [lastVideoBlob, setLastVideoBlob] = useState<Blob | null>(null);
  const [isSimulationMode, setIsSimulationMode] = useState(false);

  const [initialFormValues, setInitialFormValues] =
    useState<GenerateVideoParams | null>(null);

  const [needsApiKey, setNeedsApiKey] = useState(false);
  const [isCheckingKey, setIsCheckingKey] = useState(true);

  // Connection Configuration State with Persistence
  const [connectionConfig, setConnectionConfig] = useState<VertexConnectionConfig>(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEY);
      if (saved) {
        return JSON.parse(saved);
      }
    } catch (e) {
      console.warn('Failed to parse saved config', e);
    }
    // Hardcoded defaults requested by Administrator
    return {
      project: 'vertex-ai-runner-485313',
      location: 'us-central1',
      apiKey: 'AQ.Ab8RN6KF8rRvVBGa-yhvWLeFucKynMMKrOsqfakeClK5wuD9gg'
    };
  });

  // Modals state
  // Default to false so it works "out of the box" with hardcoded credentials
  const [showDeploymentGuide, setShowDeploymentGuide] = useState(false);
  const [showDiagnostics, setShowDiagnostics] = useState(false);

  // Persist configuration whenever it changes
  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(connectionConfig));
  }, [connectionConfig]);

  useEffect(() => {
    const checkApiKey = async () => {
      // If we have a manually configured API key in settings, we don't need to ask the user
      // via the standard dialog.
      if (connectionConfig.apiKey && connectionConfig.apiKey.trim().length > 0) {
        setNeedsApiKey(false);
        setIsCheckingKey(false);
        return;
      }

      try {
        if (window.aistudio && window.aistudio.hasSelectedApiKey) {
          const hasKey = await window.aistudio.hasSelectedApiKey();
          setNeedsApiKey(!hasKey);
        }
      } catch (error) {
        console.error('Failed to check API key:', error);
      } finally {
        setIsCheckingKey(false);
      }
    };
    checkApiKey();
  }, [connectionConfig.apiKey]);

  const handleApiKeySelected = useCallback(async () => {
    if (window.aistudio && window.aistudio.openSelectKey) {
      await window.aistudio.openSelectKey();
    }
    // Race condition mitigation: assume success
    setNeedsApiKey(false);
  }, []);

  const showStatusError = (message: string) => {
    setErrorMessage(message);
    setAppState(AppState.ERROR);
  };

  const handleGenerate = useCallback(async (params: GenerateVideoParams) => {
    setAppState(AppState.LOADING);
    setErrorMessage(null);
    setLastConfig(params);
    setInitialFormValues(null);
    setIsSimulationMode(false);

    try {
      // Pass connectionConfig to the service
      const {objectUrl, blob, video, isSimulation} = await generateVideo(params, connectionConfig);
      setVideoUrl(objectUrl);
      setLastVideoBlob(blob);
      setLastVideoObject(video);
      setIsSimulationMode(!!isSimulation);
      setAppState(AppState.SUCCESS);
    } catch (error) {
      console.error('Video generation failed:', error);
      const errorMessage =
        error instanceof Error ? error.message : 'An unknown error occurred.';

      let userFriendlyMessage = `Video generation failed: ${errorMessage}`;
      let shouldPromptKey = false;

      if (typeof errorMessage === 'string') {
        if (errorMessage.includes('Requested entity was not found.')) {
          userFriendlyMessage =
            `Model Not Found (404). Ensure Model ID '${params.model}' is enabled in Project '${connectionConfig.project}' and location '${connectionConfig.location}'.`;
            // Do not prompt key for 404, prompt to check config
            setShowDeploymentGuide(true);
        } else if (
          errorMessage.includes('API_KEY_INVALID') ||
          errorMessage.includes('API key not valid') ||
          errorMessage.toLowerCase().includes('permission denied') ||
          errorMessage.includes('403')
        ) {
          userFriendlyMessage =
            'Your API key is invalid or lacks permissions. Please check the configured API key in Settings.';
            // If they have a custom key set, open settings instead of generic prompt
            if (connectionConfig.apiKey) {
               setShowDeploymentGuide(true);
            } else {
               shouldPromptKey = true;
            }
        }
      }

      if (shouldPromptKey) {
        setNeedsApiKey(true);
        setAppState(AppState.IDLE); // Go back to idle to show dialog
      } else {
        setErrorMessage(userFriendlyMessage);
        setAppState(AppState.ERROR);
      }
    }
  }, [connectionConfig]);

  const handleRetry = useCallback(() => {
    if (lastConfig) {
      handleGenerate(lastConfig);
    }
  }, [lastConfig, handleGenerate]);

  const handleNewVideo = useCallback(() => {
    setAppState(AppState.IDLE);
    setVideoUrl(null);
    setErrorMessage(null);
    setLastConfig(null);
    setLastVideoObject(null);
    setLastVideoBlob(null);
    setInitialFormValues(null);
    setIsSimulationMode(false);
  }, []);

  const handleTryAgainFromError = useCallback(() => {
    if (lastConfig) {
      setInitialFormValues(lastConfig);
      setAppState(AppState.IDLE);
      setErrorMessage(null);
    } else {
      handleNewVideo();
    }
  }, [lastConfig, handleNewVideo]);

  const handleExtend = useCallback(async () => {
    if (lastConfig && lastVideoBlob && lastVideoObject) {
      try {
        const file = new File([lastVideoBlob], 'last_video.mp4', {
          type: lastVideoBlob.type,
        });
        const videoFile: VideoFile = {file, base64: ''};

        setInitialFormValues({
          ...lastConfig,
          mode: GenerationMode.EXTEND_VIDEO,
          prompt: '', 
          inputVideo: videoFile, 
          inputVideoObject: lastVideoObject, 
          resolution: Resolution.P720, 
          startFrame: null,
          endFrame: null,
          referenceImages: [],
          styleImage: null,
          isLooping: false,
        });

        setAppState(AppState.IDLE);
        setVideoUrl(null);
        setErrorMessage(null);
      } catch (error) {
        console.error('Failed to process video for extension:', error);
        const message =
          error instanceof Error ? error.message : 'An unknown error occurred.';
        showStatusError(`Failed to prepare video for extension: ${message}`);
      }
    }
  }, [lastConfig, lastVideoBlob, lastVideoObject]);

  const renderError = (message: string) => (
    <div className="text-center bg-red-900/20 border border-red-500/50 p-8 rounded-2xl backdrop-blur-md">
      <h2 className="text-2xl font-bold text-red-400 mb-4">Generation Failed</h2>
      <p className="text-red-300 mb-6 max-w-md mx-auto">{message}</p>
      <div className="flex justify-center gap-4">
          <button
            onClick={() => setShowDeploymentGuide(true)}
            className="px-6 py-2 bg-gray-700 hover:bg-gray-600 text-white font-medium rounded-xl transition-all"
          >
             Check Settings
          </button>
          <button
            onClick={handleTryAgainFromError}
            className="px-8 py-2 bg-red-600/80 hover:bg-red-600 text-white font-semibold rounded-xl transition-all shadow-lg shadow-red-900/20">
            Try Again
          </button>
      </div>
    </div>
  );

  const canExtend = lastConfig?.resolution === Resolution.P720;

  if (isCheckingKey) {
    return <div className="min-h-screen bg-[#0a0a0f] flex items-center justify-center">Loading...</div>;
  }

  if (needsApiKey) {
    return <ApiKeyDialog onContinue={handleApiKeySelected} />;
  }

  return (
    <div className="min-h-screen bg-[#0a0a0f] text-gray-200 flex flex-col font-sans overflow-x-hidden relative selection:bg-indigo-500/30">
      {/* Background Ambience */}
      <div className="fixed inset-0 pointer-events-none z-0">
        <div className="absolute top-[-20%] left-[-10%] w-[50%] h-[50%] bg-indigo-900/20 rounded-full blur-[120px]" />
        <div className="absolute bottom-[-20%] right-[-10%] w-[50%] h-[50%] bg-violet-900/10 rounded-full blur-[120px]" />
      </div>

      <DiagnosticsModal 
        isOpen={showDiagnostics}
        onClose={() => setShowDiagnostics(false)}
        config={connectionConfig}
      />

      <DeploymentGuideModal
        isOpen={showDeploymentGuide}
        onClose={() => setShowDeploymentGuide(false)}
        config={connectionConfig}
        onConfigChange={setConnectionConfig}
        onRunDiagnostics={() => setShowDiagnostics(true)}
      />

      {isSimulationMode && (
        <div className="fixed top-20 right-4 sm:right-8 z-50 animate-fade-in flex flex-col items-end gap-2">
          <div className="bg-amber-500/10 border border-amber-500/40 text-amber-200 px-4 py-2 rounded-full text-xs font-bold backdrop-blur-md flex items-center gap-2 shadow-[0_0_15px_rgba(245,158,11,0.2)]">
            <span className="w-2 h-2 rounded-full bg-amber-500 animate-pulse"></span>
            SIMULATION MODE (API 403 Bypass)
          </div>
          <a 
            href={`https://console.cloud.google.com/apis/library/generativelanguage.googleapis.com?project=${connectionConfig.project}`}
            target="_blank"
            rel="noreferrer"
            className="text-[10px] text-amber-400 hover:text-amber-300 underline underline-offset-2"
          >
            Fix permissions in Google Cloud Console
          </a>
        </div>
      )}

      {/* Header */}
      <header className="py-5 px-6 sm:px-10 flex items-center justify-between border-b border-white/5 bg-[#0a0a0f]/80 backdrop-blur-md sticky top-0 z-50">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-gradient-to-br from-indigo-500 to-violet-600 rounded-xl flex items-center justify-center shadow-lg shadow-indigo-500/20">
            <svg className="w-6 h-6 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14.752 11.168l-3.197-2.132A1 1 0 0010 9.87v4.263a1 1 0 001.555.832l3.197-2.132a1 1 0 000-1.664z" />
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
            </svg>
          </div>
