  const handleChipSelect = (chipId: string) => {
    setSelectedChip(chipId);
    // Updated mapping to new Vertex model IDs
    if (chipId === 'veo-fast') setModel(VeoModel.VEO_FAST); // veo-3.1-fast-generate-preview
    else if (chipId === 'veo-pro') setModel(VeoModel.VEO); // veo-3.1-generate-preview
