  const handleModeSwitch = (mode: GenerationMode) => {
      setGenerationMode(mode);
      if (mode === GenerationMode.FRAMES_TO_VIDEO) {
          // Clear prompt if switching to Frames mode to avoid conflicts with "text-based" defaults
