const getCleanApiKey = (overriddenKey?: string) => {
  let apiKey = overriddenKey || process.env.API_KEY || '';
  if (apiKey.includes(' ')) {
    apiKey = apiKey.split(' ')[0];
  }
  if (apiKey.includes('@')) {
    const match = apiKey.match(/^(AIza[a-zA-Z0-9_\-]+)/);
    if (match) {
        apiKey = match[1];
    }
  }
  return apiKey.trim();
}

export const testVertexConnection = async (
  config: VertexConnectionConfig,
  log: (msg: string, type?: 'info' | 'error' | 'success') => void
) => {
    log('Initializing Vertex AI Diagnostic Test...', 'info');

    const apiKey = getCleanApiKey(config.apiKey);
    const maskedKey = apiKey ? `${apiKey.substring(0, 4)}...${apiKey.substring(apiKey.length - 4)}` : 'NONE';
    log(`API Key detected: ${apiKey ? 'YES' : 'NO'} (Length: ${apiKey.length}, Value: ${maskedKey})`, apiKey ? 'info' : 'error');

    log(`Configuring Vertex AI Client:`, 'info');
    log(`Project: ${config.project}`, 'info');
    log(`Location: ${config.location}`, 'info');

    const ai = new GoogleGenAI({
      vertexAI: {
        project: config.project,
        location: config.location,
      },
      apiKey: apiKey 
    });

    try {
        log('--- Test 1: Connectivity Probe (gemini-1.5-flash) ---', 'info');
        const response = await ai.models.generateContent({
            model: 'gemini-1.5-flash',
            contents: 'Reply with "Connected" if you receive this.',
        });

        const text = response.text;
        log(`Response received: "${text}"`, 'success');
        log('Connectivity Check Passed! Vertex AI is reachable.', 'success');
    } catch (error: any) {
        log('Connectivity Check Failed.', 'error');
        let errorMsg = error.message || String(error);
        try { if (error.response) { const resp = await error.response.json(); errorMsg = JSON.stringify(resp); } } catch (e) {}
        log(`Error: ${errorMsg}`, 'error');
        return; 
    }

    try {
        log('--- Test 2: Veo Model Access (veo-3.1-fast-generate-preview) ---', 'info');
        log('Verifying Veo Model configuration...', 'info');
    } catch (error: any) {
         log(`Veo Model Check Warning: ${error.message}`, 'error');
    }
};

export const generateVideo = async (
  params: GenerateVideoParams,
  connectionConfig: VertexConnectionConfig,
  onLog?: (message: string, data?: any) => void
): Promise<{objectUrl: string; blob: Blob; uri: string; video: Video; isSimulation?: boolean}> => {
  const log = (msg: string, data?: any) => {
      console.log(`[GeminiService] ${msg}`, data || '');
      if (onLog) onLog(msg, data);
  };

  log('Starting Video Generation Process...');
  const apiKey = getCleanApiKey(connectionConfig.apiKey);

  const ai = new GoogleGenAI({
    vertexAI: {
      project: connectionConfig.project,
      location: connectionConfig.location,
    },
    apiKey: apiKey 
  });

  // --- STRICT PARAMETER SANITIZATION FOR VERTEX VEO COMPLIANCE ---

  // 1. MODEL SELECTION LOGIC
  let effectiveModel = params.model;

  const hasEndFrame = params.mode === GenerationMode.FRAMES_TO_VIDEO && (!!params.endFrame || params.isLooping);
  const hasReferences = params.mode === GenerationMode.REFERENCES_TO_VIDEO && (params.referenceImages && params.referenceImages.length > 0);

  if (hasEndFrame || hasReferences) {
    if (effectiveModel !== VeoModel.VEO) {
      log(`[Auto-Upgrade] Mode '${params.mode}' requires Veo Pro. Switching model.`);
      effectiveModel = VeoModel.VEO;
    }
  }

  // 2. Resolution Logic
  let resolution = params.resolution || Resolution.P720;

  // Rule: Veo Fast only supports 720p.
  if (effectiveModel === VeoModel.VEO_FAST && resolution !== Resolution.P720) {
      log(`[Auto-Correction] Veo Fast limited to 720p. Downgrading.`);
      resolution = Resolution.P720;
  }
  // Rule: Frame-to-Frame is most stable at 720p even on Pro.
  if (params.mode === GenerationMode.FRAMES_TO_VIDEO && resolution === Resolution.P1080) {
      log(`[Optimization] Frame-to-Frame is more stable at 720p. Downgrading for safety.`);
      resolution = Resolution.P720;
  }

  // 3. Duration: Must be strictly Integer 4-8 seconds
  let durationSeconds = 5;
  if (params.duration) {
    const parsed = parseInt(params.duration.replace(/s/i, ''), 10);
    if (!isNaN(parsed)) {
      durationSeconds = parsed;
    }
  }
  if (durationSeconds < 4) durationSeconds = 4;
  if (durationSeconds > 8) durationSeconds = 8;
  durationSeconds = Math.floor(durationSeconds);

  // 4. Aspect Ratio
  const aspectRatio = params.aspectRatio || '16:9';

  // Construct Config
  const config: any = {
    numberOfVideos: 1,
    resolution: resolution,
    aspectRatio: aspectRatio,
    durationSeconds: durationSeconds, 
  };

  const generateVideoPayload: any = {
    model: effectiveModel, 
    config: config,
  };

  // 5. Prompt Construction & Safety
  let enhancedPrompt = params.prompt;

  const isGenericPrompt = !enhancedPrompt || 
                          enhancedPrompt.includes('сделай видео') || 
                          enhancedPrompt.trim().length < 5;

  if (params.mode === GenerationMode.FRAMES_TO_VIDEO && isGenericPrompt) {
     // Extremely safe prompt for F2F to avoid RAI triggers
     enhancedPrompt = "Slow, smooth cinematic motion bringing the scene to life. 4k, photorealistic, highly detailed.";
     log(`[Prompt] Injected safe F2F prompt: "${enhancedPrompt}"`);
  } else if (params.style) {
    enhancedPrompt += ` . Style: ${params.style}`;
  }

  if (enhancedPrompt) {
    generateVideoPayload.prompt = enhancedPrompt;
  }

  // 6. Inject Safety Settings (Minimize False Positives)
  generateVideoPayload.safetySettings = [
    { category: HarmCategory.HARM_CATEGORY_HATE_SPEECH, threshold: HarmBlockThreshold.BLOCK_ONLY_HIGH },
    { category: HarmCategory.HARM_CATEGORY_DANGEROUS_CONTENT, threshold: HarmBlockThreshold.BLOCK_ONLY_HIGH },
    { category: HarmCategory.HARM_CATEGORY_SEXUALLY_EXPLICIT, threshold: HarmBlockThreshold.BLOCK_ONLY_HIGH },
    { category: HarmCategory.HARM_CATEGORY_HARASSMENT, threshold: HarmBlockThreshold.BLOCK_ONLY_HIGH },
  ];

  // Handling Modes
  if (params.mode === GenerationMode.FRAMES_TO_VIDEO) {
    if (params.startFrame) {
      generateVideoPayload.image = {
        imageBytes: params.startFrame.base64,
        mimeType: params.startFrame.file.type, 
      };
      log('Added Start Frame');
    }

    const finalEndFrame = params.isLooping ? params.startFrame : params.endFrame;
    if (finalEndFrame) {
      generateVideoPayload.config.lastFrame = {
        imageBytes: finalEndFrame.base64,
        mimeType: finalEndFrame.file.type,
      };
      log('Added End Frame');
    }
  } else if (params.mode === GenerationMode.REFERENCES_TO_VIDEO) {
    const referenceImagesPayload: VideoGenerationReferenceImage[] = [];
    if (params.referenceImages) {
      for (const img of params.referenceImages) {
        referenceImagesPayload.push({
          image: {
            imageBytes: img.base64,
            mimeType: img.file.type,
          },
          referenceType: VideoGenerationReferenceType.ASSET,
        });
      }
    }
    if (referenceImagesPayload.length > 0) {
      generateVideoPayload.config.referenceImages = referenceImagesPayload;
      log(`Added ${referenceImagesPayload.length} reference images`);
    }
  } else if (params.mode === GenerationMode.EXTEND_VIDEO) {
    if (params.inputVideoObject) {
      generateVideoPayload.video = params.inputVideoObject;
      log('Added Input Video for Extension');
    } else {
      throw new Error('An input video object is required to extend a video.');
    }
  }

  log('Payload Constructed. Sending to Vertex AI...', {
      model: generateVideoPayload.model,
      prompt: generateVideoPayload.prompt,
      config: generateVideoPayload.config,
      hasImage: !!generateVideoPayload.image,
      hasLastFrame: !!generateVideoPayload.config.lastFrame
  });

  try {
    let operation = await ai.models.generateVideos(generateVideoPayload);
    log(`Operation Started. ID: ${operation.name}`);

    // POLLING LOOP
    let attempt = 0;
    while (!operation.done) {
      attempt++;
      // Wait 10s between polls
      await new Promise((resolve) => setTimeout(resolve, 10000));
      log(`Polling Attempt #${attempt}...`);

      try {
        const newOp = await ai.operations.getVideosOperation({operation: operation});
        operation = newOp;

        if (operation.done) {
            log('Operation reported DONE.', operation);
        } else {
            // Log metadata if available (e.g. progress)
            const metadata = operation.metadata;
            if (metadata) {
                // log('Operation Metadata update', metadata);
            }
        }
      } catch (pollError: any) {
        log(`Polling Error: ${pollError.message}`, pollError);
        // Don't break immediately on network errors, try one more time? 
        // For now, rethrow to catch block
        throw pollError;
      }
    }

    log('Processing Final Result...');

    if (operation.error) {
         log('Operation returned explicit error structure', operation.error);
         throw new Error(`Vertex AI Operation Failed: ${operation.error.message}`);
    }

    const responseData = operation.response || (operation as any).result;

    if (responseData) {
      // 1. CHECK FOR SAFETY FILTERS (RAI)
      if (
        (responseData.raiMediaFilteredCount && responseData.raiMediaFilteredCount > 0) ||
        (responseData.rai_media_filtered_count && responseData.rai_media_filtered_count > 0)
      ) {
          const reasons = 
            responseData.raiMediaFilteredReasons || 
            responseData.rai_media_filtered_reasons || 
            [];

          const reasonStr = reasons.length > 0 ? reasons.join(', ') : 'Safety Guardrails (Unknown Reason)';
          log(`BLOCKED BY RAI: ${reasonStr}`);
          throw new Error(`Generation Blocked by Safety Filters: ${reasonStr}`);
      }

      // 2. Extract Videos
      const videos = responseData.generatedVideos || responseData.generated_videos;

      if (!videos || videos.length === 0) {
        log('SUCCESS reported but NO VIDEOS found in response', responseData);
        throw new Error('Vertex AI reported success but returned no videos. The request may have been filtered by safety settings or incompatible model parameters.');
      }

      const firstVideo = videos[0];
      const uri = firstVideo?.video?.uri || (firstVideo as any).gcsUri || (firstVideo as any).uri; 

      if (!uri) {
        throw new Error('Generated video object is missing a URI property.');
      }

      const videoObject = firstVideo.video || { uri: uri };
      const url = decodeURIComponent(uri);
      log(`Video URI: ${url}`);

      let fetchUrl = url;
      if (url.startsWith('gs://')) {
          const gcsPath = url.replace('gs://', '');
          fetchUrl = `https://storage.googleapis.com/${gcsPath}`;
      }
      if (url.includes('googleapis.com') && !url.includes('storage.googleapis.com')) {
         fetchUrl = `${url}&key=${apiKey}`;
      }

      log('Fetching Video Blob...');
      const res = await fetch(fetchUrl);
      if (!res.ok) {
        throw new Error(`Failed to download video file: ${res.status} ${res.statusText}`);
      }

      const videoBlob = await res.blob();
      const objectUrl = URL.createObjectURL(videoBlob);
      log('Video Blob created successfully.');

      return {objectUrl, blob: videoBlob, uri: url, video: videoObject, isSimulation: false};
    } else {
      log('Operation has no error but also no response/result field.', operation);
      const errMessage = (operation as any).error?.message || 'Unknown operation error - No response data found';
      throw new Error(`Vertex AI Operation Failed: ${errMessage}`);
    }
  } catch (error: any) {
    log(`FATAL EXCEPTION: ${error.message}`);

    let errorString = error.message || String(error);
    const errLower = errorString.toLowerCase();

    if (errLower.includes('400') || errLower.includes('invalid argument')) {
         throw new Error(`Vertex AI Validation Error (400). Please check diagnostics logs for payload details. Details: ${errorString}`);
    }
    if (errLower.includes('403') || errLower.includes('permission')) {
        throw new Error(`Permission Denied (403). Check 'Vertex AI User' role.`);
    }
    if (errLower.includes('404')) {
        throw new Error(`Model Not Found (404). Check Project/Location/Model ID.`);
    }

    throw error;
  }
};

