import {Video} from '@google/genai';
import React, {useCallback, useEffect, useState} from 'react';
import LoadingIndicator from './components/LoadingIndicator';
import PromptForm from './components/PromptForm';
import VideoResult from './components/VideoResult';
import ApiKeyDialog from './components/ApiKeyDialog';
import DiagnosticsModal from './components/DiagnosticsModal';
import DeploymentGuideModal from './components/DeploymentGuideModal';
import GalleryModal from './components/GalleryModal';
import {generateVideo} from './services/geminiService';
import {PlusIcon, WalletIcon, ActivityIcon, ServerIcon, HistoryIcon} from './components/icons';
import {
  AppState,
  AspectRatio,
  GenerateVideoParams,
  GenerationMode,
  Resolution,
  VideoFile,
  VertexConnectionConfig,
  GalleryItem
} from './types';

declare global {
  interface AIStudio {
    hasSelectedApiKey: () => Promise<boolean>;
    openSelectKey: () => Promise<void>;
  }
}

const STORAGE_KEY = 'video_zavod_vertex_config';
const GALLERY_KEY = 'video_zavod_gallery_history';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.IDLE);
  const [videoUrl, setVideoUrl] = useState<string | null>(null);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [lastConfig, setLastConfig] = useState<GenerateVideoParams | null>(
    null,
  );
  const [lastVideoObject, setLastVideoObject] = useState<Video | null>(null);
  const [lastVideoBlob, setLastVideoBlob] = useState<Blob | null>(null);
  const [isSimulationMode, setIsSimulationMode] = useState(false);

  const [initialFormValues, setInitialFormValues] =
    useState<GenerateVideoParams | null>(null);

  const [needsApiKey, setNeedsApiKey] = useState(false);
  const [isCheckingKey, setIsCheckingKey] = useState(true);

  // Connection Configuration State with Persistence
  const [connectionConfig, setConnectionConfig] = useState<VertexConnectionConfig>(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEY);
      if (saved) {
        return JSON.parse(saved);
      }
    } catch (e) {
      console.warn('Failed to parse saved config', e);
    }
    return {
      project: 'vertex-ai-runner-485313',
      location: 'us-central1',
      apiKey: 'AQ.Ab8RN6KF8rRvVBGa-yhvWLeFucKynMMKrOsqfakeClK5wuD9gg'
    };
  });

  // Gallery History State
  const [galleryItems, setGalleryItems] = useState<GalleryItem[]>(() => {
      try {
          const saved = localStorage.getItem(GALLERY_KEY);
          return saved ? JSON.parse(saved) : [];
      } catch (e) {
          return [];
      }
  });

  // Modals state
  const [showDeploymentGuide, setShowDeploymentGuide] = useState(false);
  const [showDiagnostics, setShowDiagnostics] = useState(false);
  const [showGallery, setShowGallery] = useState(false);

  // State to hold logs from the current generation session
  const [generationLogs, setGenerationLogs] = useState<any[]>([]);

  // Persist configuration whenever it changes
  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(connectionConfig));
  }, [connectionConfig]);

  // Persist Gallery (Metadata only essentially, URLs are blobs that expire)
  useEffect(() => {
      // We strip the blob URL for long term storage as it won't work after reload, 
      // but for current session it stays in state.
      // In a real app we'd upload to cloud storage.
      const safeToStore = galleryItems.map(item => ({
          ...item,
          videoUrl: null // Blob URLs expire, so we don't save them to LS to avoid confusion on reload
      }));
      localStorage.setItem(GALLERY_KEY, JSON.stringify(safeToStore));
  }, [galleryItems]);

  useEffect(() => {
    const checkApiKey = async () => {
      if (connectionConfig.apiKey && connectionConfig.apiKey.trim().length > 0) {
        setNeedsApiKey(false);
        setIsCheckingKey(false);
        return;
      }
      try {
        if (window.aistudio && window.aistudio.hasSelectedApiKey) {
          const hasKey = await window.aistudio.hasSelectedApiKey();
          setNeedsApiKey(!hasKey);
        }
      } catch (error) {
        console.error('Failed to check API key:', error);
      } finally {
        setIsCheckingKey(false);
      }
    };
    checkApiKey();
  }, [connectionConfig.apiKey]);

  const handleApiKeySelected = useCallback(async () => {
    if (window.aistudio && window.aistudio.openSelectKey) {
      await window.aistudio.openSelectKey();
    }
    setNeedsApiKey(false);
  }, []);

  const showStatusError = (message: string) => {
    setErrorMessage(message);
    setAppState(AppState.ERROR);
  };

  const addLog = (message: string, data?: any) => {
      setGenerationLogs(prev => [...prev, {
          id: Date.now(),
          timestamp: new Date().toLocaleTimeString(),
          type: 'info',
          message: `${message} ${data ? JSON.stringify(data) : ''}`
      }]);
  };

  const addToGallery = (item: GalleryItem) => {
      setGalleryItems(prev => [item, ...prev]);
  };

  const handleDeleteGalleryItem = (id: string) => {
      setGalleryItems(prev => prev.filter(item => item.id !== id));
  };

  const handleGenerate = useCallback(async (params: GenerateVideoParams) => {
    setAppState(AppState.LOADING);
    setErrorMessage(null);
    setLastConfig(params);
    setInitialFormValues(null);
    setIsSimulationMode(false);

    // Clear previous logs
    setGenerationLogs([]);

    try {
      const {objectUrl, blob, video, isSimulation} = await generateVideo(
          params, 
          connectionConfig,
          (msg, data) => addLog(msg, data)
      );

      setVideoUrl(objectUrl);
      setLastVideoBlob(blob);
      setLastVideoObject(video);
      setIsSimulationMode(!!isSimulation);
      setAppState(AppState.SUCCESS);

      // Add to Gallery History
      addToGallery({
          id: Date.now().toString(),
          timestamp: Date.now(),
          status: 'succeeded',
          params: params,
          videoUrl: objectUrl,
          cost: 40 // Mock cost based on Veo pricing/screenshot
      });

    } catch (error) {
      console.error('Video generation failed:', error);
      const errorMessage =
        error instanceof Error ? error.message : 'An unknown error occurred.';

      let userFriendlyMessage = `Video generation failed: ${errorMessage}`;
      let shouldPromptKey = false;

      // Add failed attempt to gallery
      addToGallery({
        id: Date.now().toString(),
        timestamp: Date.now(),
        status: 'failed',
        params: params,
        error: errorMessage,
        cost: 0
      });

      if (typeof errorMessage === 'string') {
        if (errorMessage.includes('Requested entity was not found.')) {
          userFriendlyMessage =
            `Model Not Found (404). Ensure Model ID '${params.model}' is enabled in Project '${connectionConfig.project}' and location '${connectionConfig.location}'.`;
            setShowDeploymentGuide(true);
        } else if (
          errorMessage.includes('API_KEY_INVALID') ||
          errorMessage.includes('API key not valid') ||
          errorMessage.toLowerCase().includes('permission denied') ||
          errorMessage.includes('403')
        ) {
          userFriendlyMessage =
            'Your API key is invalid or lacks permissions. Please check the configured API key in Settings.';
            if (connectionConfig.apiKey) {
               setShowDeploymentGuide(true);
            } else {
               shouldPromptKey = true;
            }
        }
      }

      if (shouldPromptKey) {
        setNeedsApiKey(true);
        setAppState(AppState.IDLE); 
      } else {
        setErrorMessage(userFriendlyMessage);
        setAppState(AppState.ERROR);
      }
    }
  }, [connectionConfig]);

  const handleRetry = () => {
    if (lastConfig) {
      handleGenerate(lastConfig);
    }
  };

  const handleNewVideo = () => {
    setAppState(AppState.IDLE);
    setVideoUrl(null);
    setLastVideoBlob(null);
    setLastVideoObject(null);
    setErrorMessage(null);
    setLastConfig(null);
  };

  const handleExtendVideo = () => {
    if (lastConfig && lastVideoObject) {
      const extendParams: GenerateVideoParams = {
        ...lastConfig,
        mode: GenerationMode.EXTEND_VIDEO,
        inputVideoObject: lastVideoObject,
        prompt: "Continue the video smoothly.", 
      };
      setInitialFormValues(extendParams);
      setAppState(AppState.IDLE);
    }
  };

  return (
    <div className="min-h-screen bg-black text-white font-sans selection:bg-indigo-500/30 selection:text-indigo-200">

      {/* Header */}
      <header className="sticky top-0 z-40 w-full border-b border-white/10 bg-black/80 backdrop-blur-md">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 rounded-lg bg-gradient-to-tr from-indigo-500 to-violet-500 flex items-center justify-center shadow-lg shadow-indigo-500/20">
                <span className="font-bold text-white text-lg">V</span>
            </div>
            <h1 className="text-xl font-bold tracking-tight bg-clip-text text-transparent bg-gradient-to-r from-white to-gray-400">
              VIDEO_ZAVOD
            </h1>
          </div>

          <div className="flex items-center gap-3">
             <button 
               onClick={() => setShowDiagnostics(true)}
               className="p-2 text-gray-400 hover:text-white transition-colors rounded-lg hover:bg-white/5"
               title="System Diagnostics"
             >
                <ActivityIcon className="w-5 h-5" />
             </button>

             <button 
               onClick={() => setShowDeploymentGuide(true)}
               className="p-2 text-gray-400 hover:text-white transition-colors rounded-lg hover:bg-white/5"
               title="Connection Settings"
             >
                <ServerIcon className="w-5 h-5" />
             </button>

             <div className="h-6 w-px bg-white/10 mx-1"></div>

             {/* Gallery Button */}
             <button 
               onClick={() => setShowGallery(true)}
               className="flex items-center gap-2 px-4 py-2 bg-[#1a1a1f] hover:bg-[#25252b] border border-white/10 text-gray-300 text-xs font-medium rounded-lg transition-all"
             >
               <HistoryIcon className="w-4 h-4" />
               <span className="hidden sm:inline">History</span>
             </button>

             {/* Wallet / Account Placeholder */}
             <div className="flex items-center gap-2 px-4 py-2 bg-[#1a1a1f] border border-white/10 text-gray-300 text-xs font-medium rounded-lg">
                <WalletIcon className="w-4 h-4 text-indigo-400" />
                <span>480 Tokens</span>
             </div>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12">
        {needsApiKey ? (
          <ApiKeyDialog onContinue={handleApiKeySelected} />
        ) : (
          <>
            {appState === AppState.LOADING && <LoadingIndicator />}

            {appState === AppState.SUCCESS && videoUrl && (
              <VideoResult
                videoUrl={videoUrl}
                onRetry={handleRetry}
                onNewVideo={handleNewVideo}
                onExtend={handleExtendVideo}
                canExtend={!isSimulationMode} // Only allow extending real videos
                aspectRatio={lastConfig?.aspectRatio || AspectRatio.LANDSCAPE}
              />
            )}

            {/* Show form when IDLE or ERROR (to allow retry/edit) */}
            {(appState === AppState.IDLE || appState === AppState.ERROR) && (
              <>
                {appState === AppState.ERROR && errorMessage && (
                  <div className="mb-8 p-4 bg-red-900/20 border border-red-500/30 rounded-xl flex items-start gap-3">
                      <div className="p-1 bg-red-500/10 rounded-full">
                          <ActivityIcon className="w-5 h-5 text-red-400" />
                      </div>
                      <div>
                          <h3 className="text-red-400 font-bold text-sm">Generation Failed</h3>
                          <p className="text-red-200/70 text-sm mt-1">{errorMessage}</p>
                          <button 
                            onClick={() => setShowDiagnostics(true)}
                            className="text-xs text-red-300 underline mt-2 hover:text-white"
                          >
                            View Diagnostics Logs
                          </button>
                      </div>
                  </div>
                )}

                <PromptForm 
                    onGenerate={handleGenerate} 
                    initialValues={initialFormValues || (lastConfig ? lastConfig : null)}
                />
              </>
            )}
          </>
        )}
      </main>

      {/* Footer */}
      <footer className="border-t border-white/5 mt-12 py-8 text-center text-gray-600 text-xs">
        <p>Powered by Google Veo & Vertex AI</p>
      </footer>

      {/* Modals */}
      <DeploymentGuideModal 
        isOpen={showDeploymentGuide} 
        onClose={() => setShowDeploymentGuide(false)}
        config={connectionConfig}
        onConfigChange={setConnectionConfig}
        onRunDiagnostics={() => {
            setShowDeploymentGuide(false);
            setShowDiagnostics(true);
        }}
      />

      <DiagnosticsModal 
        isOpen={showDiagnostics}
        onClose={() => setShowDiagnostics(false)}
        config={connectionConfig}
        externalLogs={generationLogs}
      />

      <GalleryModal 
        isOpen={showGallery}
        onClose={() => setShowGallery(false)}
        items={galleryItems}
        onDeleteItem={handleDeleteGalleryItem}
      />

    </div>
  );
};

export default App;

