import {Video} from '@google/genai';
import React, {useCallback, useEffect, useRef, useState} from 'react';
import {
  AspectRatio,
  GenerateVideoParams,
  GenerationMode,
  ImageFile,
  Resolution,
  VeoModel,
  VideoFile,
  VideoStyle,
} from '../types';
import {
  ArrowRightIcon,
  ChevronDownIcon,
  FilmIcon,
  FramesModeIcon,
  PlusIcon,
  ReferencesModeIcon,
  SparklesIcon,
  TextModeIcon,
  WandIcon,
  XMarkIcon,
  TvIcon,
  SlidersHorizontalIcon,
  RectangleStackIcon
} from './icons';

interface PromptFormProps {
  onGenerate: (params: GenerateVideoParams) => void;
