import {
  GoogleGenAI,
  Video,
  VideoGenerationReferenceImage,
  VideoGenerationReferenceType,
  HarmCategory,
  HarmBlockThreshold,
  GenerateContentResponse
} from '@google/genai';
import {GenerateVideoParams, GeneratePhotoParams, GenerationMode, VertexConnectionConfig, VeoModel, PhotoModel, Resolution, AspectRatio} from '../types';

const getCleanApiKey = (overriddenKey?: string) => {
  let apiKey = overriddenKey || process.env.API_KEY || '';
  if (apiKey.includes(' ')) {
    apiKey = apiKey.split(' ')[0];
  }
  if (apiKey.includes('@')) {
    const match = apiKey.match(/^(AIza[a-zA-Z0-9_\-]+)/);
    if (match) {
        apiKey = match[1];
    }
  }
  return apiKey.trim();
}

export const testVertexConnection = async (
  config: VertexConnectionConfig,
  log: (msg: string, type?: 'info' | 'error' | 'success') => void
) => {
    log('Initializing API Diagnostic Test...', 'info');

    const apiKey = getCleanApiKey(config.apiKey);
    const maskedKey = apiKey ? `${apiKey.substring(0, 4)}...${apiKey.substring(apiKey.length - 4)}` : 'NONE';
    log(`API Key detected: ${apiKey ? 'YES' : 'NO'} (Length: ${apiKey.length}, Value: ${maskedKey})`, apiKey ? 'info' : 'error');

    // We use standard Gemini API mode to ensure we get downloadable links
    const ai = new GoogleGenAI({
      apiKey: apiKey 
    });

    try {
        const PROBE_MODEL = 'gemini-2.0-flash'; 
        log(`--- Test 1: Connectivity Probe (${PROBE_MODEL}) ---`, 'info');
        const response = await ai.models.generateContent({
            model: PROBE_MODEL,
            contents: 'Reply with "Connected" if you receive this.',
        });

        const text = response.text;
        log(`Response received: "${text}"`, 'success');
        log('Connectivity Check Passed! Gemini API is reachable.', 'success');
    } catch (error: any) {
        log('Connectivity Check Failed.', 'error');
        let errorMsg = error.message || String(error);
        try { if (error.response) { const resp = await error.response.json(); errorMsg = JSON.stringify(resp); } } catch (e) {}
        log(`Error: ${errorMsg}`, 'error');
    }
};

export const generateImage = async (
  params: GeneratePhotoParams,
  connectionConfig: VertexConnectionConfig,
  onLog?: (message: string, data?: any) => void
): Promise<{imageUrl: string; blob: Blob}> => {
  const log = (msg: string, data?: any) => {
      console.log(`[GeminiService:Image] ${msg}`, data || '');
      if (onLog) onLog(msg, data);
  };

  log('Starting Image Generation Process...');
  const apiKey = getCleanApiKey(connectionConfig.apiKey);

  const ai = new GoogleGenAI({
    apiKey: apiKey 
  });

  const payload: any = {
    model: params.model,
    contents: {
      parts: [
        { text: params.prompt }
      ]
    },
    config: {
      imageConfig: {
        aspectRatio: params.aspectRatio,
        // imageSize only supported for Pro models (gemini-3-pro-image-preview)
        ...(params.model === PhotoModel.NANO_BANANA_PRO ? {
            imageSize: params.quality === '4K' ? '4096' : params.quality === 'HD' ? '2048' : '1024'
        } : {}) 
      }
    }
  };

  // Add reference images if any
  if (params.referenceImages && params.referenceImages.length > 0) {
    const parts = params.referenceImages.map(img => ({
      inlineData: {
        data: img.base64,
        mimeType: img.file.type
      }
    }));
    // Append prompt to parts
    payload.contents.parts = [...parts, { text: params.prompt }];
  }

  log(`Using Model: ${params.model}`);
  log(`Aspect Ratio: ${params.aspectRatio}`);

  try {
    const response: GenerateContentResponse = await ai.models.generateContent(payload);

    // Extract Image
    let base64Image: string | undefined;
    let mimeType: string | undefined;

    if (response.candidates && response.candidates.length > 0) {
      const parts = response.candidates[0].content.parts;
      for (const part of parts) {
        if (part.inlineData) {
          base64Image = part.inlineData.data;
          mimeType = part.inlineData.mimeType || 'image/png';
          break;
        }
      }
    }

    if (!base64Image) {
      throw new Error("No image data returned from API.");
    }

    log("Image received successfully.");

    // Convert Base64 to Blob
    const byteCharacters = atob(base64Image);
    const byteNumbers = new Array(byteCharacters.length);
    for (let i = 0; i < byteCharacters.length; i++) {
      byteNumbers[i] = byteCharacters.charCodeAt(i);
    }
    const byteArray = new Uint8Array(byteNumbers);
    const blob = new Blob([byteArray], { type: mimeType });
    const imageUrl = URL.createObjectURL(blob);

    return { imageUrl, blob };

  } catch (error: any) {
    log(`FATAL EXCEPTION: ${JSON.stringify(error)}`);
    throw error;
  }
};

export const generateVideo = async (
  params: GenerateVideoParams,
  connectionConfig: VertexConnectionConfig,
  onLog?: (message: string, data?: any) => void
): Promise<{objectUrl: string; blob: Blob; uri: string; video: Video; isSimulation?: boolean}> => {
  const log = (msg: string, data?: any) => {
      console.log(`[GeminiService] ${msg}`, data || '');
      if (onLog) onLog(msg, data);
  };

  log('Starting Video Generation Process (Gemini API Mode)...');
  const apiKey = getCleanApiKey(connectionConfig.apiKey);

  // Use Standard Gemini API to ensure downloadable URLs
  const ai = new GoogleGenAI({
    apiKey: apiKey 
  });

  // --- STRICT PARAMETER SANITIZATION ---

  // 1. MODEL SELECTION LOGIC
  let effectiveModel = params.model;

  const hasEndFrame = params.mode === GenerationMode.FRAMES_TO_VIDEO && (!!params.endFrame || params.isLooping);
  const hasReferences = params.mode === GenerationMode.REFERENCES_TO_VIDEO && (params.referenceImages && params.referenceImages.length > 0);

  if (hasEndFrame || hasReferences) {
    if (effectiveModel !== VeoModel.VEO) {
      log(`[Auto-Upgrade] Mode '${params.mode}' requires Veo Pro. Switching model.`);
      effectiveModel = VeoModel.VEO;
    }
  }

  // 2. Resolution Logic
  let resolution = params.resolution || Resolution.P720;

  if (effectiveModel === VeoModel.VEO_FAST && resolution !== Resolution.P720) {
      log(`[Auto-Correction] Veo Fast limited to 720p. Downgrading.`);
      resolution = Resolution.P720;
  }
  if (params.mode === GenerationMode.FRAMES_TO_VIDEO && resolution === Resolution.P1080) {
      log(`[Optimization] Frame-to-Frame is more stable at 720p. Downgrading for safety.`);
      resolution = Resolution.P720;
  }

  let aspectRatio = params.aspectRatio || AspectRatio.LANDSCAPE;
  if (params.mode === GenerationMode.REFERENCES_TO_VIDEO) {
      if (resolution !== Resolution.P720) resolution = Resolution.P720;
      if (aspectRatio !== AspectRatio.LANDSCAPE) aspectRatio = AspectRatio.LANDSCAPE;
  }

  // 3. Duration: STRICT Parsing
  let durationSeconds = 5; // Safe default
  if (params.duration) {
    // Remove non-digits
    const cleanDuration = params.duration.replace(/[^0-9]/g, '');
    const parsed = parseInt(cleanDuration, 10);
    if (!isNaN(parsed)) {
      durationSeconds = parsed;
    }
  }
  // Clamp strictly
  if (durationSeconds < 4) durationSeconds = 4;
  if (durationSeconds > 8) durationSeconds = 8;

  // Ensure it's a number
  durationSeconds = Number(durationSeconds);

  // Construct Config
  const config: any = {
    numberOfVideos: 1,
    resolution: resolution,
    aspectRatio: aspectRatio,
    durationSeconds: durationSeconds, 
  };

  const generateVideoPayload: any = {
    model: effectiveModel, 
    config: config,
  };

  // 5. Prompt Construction & Safety
  let enhancedPrompt = params.prompt;

  const isGenericPrompt = !enhancedPrompt || 
                          enhancedPrompt.includes('сделай видео') || 
                          enhancedPrompt.trim().length < 5;

  if (params.mode === GenerationMode.FRAMES_TO_VIDEO && isGenericPrompt) {
     enhancedPrompt = "Slow, smooth cinematic motion bringing the scene to life. 4k, photorealistic, highly detailed.";
     log(`[Prompt] Injected safe F2F prompt: "${enhancedPrompt}"`);
  } else if (params.style) {
    enhancedPrompt += ` . Style: ${params.style}`;
  }

  if (enhancedPrompt) {
    generateVideoPayload.prompt = enhancedPrompt;
  }

  // 6. Inject Safety Settings
  generateVideoPayload.safetySettings = [
    { category: HarmCategory.HARM_CATEGORY_HATE_SPEECH, threshold: HarmBlockThreshold.BLOCK_ONLY_HIGH },
    { category: HarmCategory.HARM_CATEGORY_DANGEROUS_CONTENT, threshold: HarmBlockThreshold.BLOCK_ONLY_HIGH },
    { category: HarmCategory.HARM_CATEGORY_SEXUALLY_EXPLICIT, threshold: HarmBlockThreshold.BLOCK_ONLY_HIGH },
    { category: HarmCategory.HARM_CATEGORY_HARASSMENT, threshold: HarmBlockThreshold.BLOCK_ONLY_HIGH },
  ];

  // Handling Modes
  if (params.mode === GenerationMode.FRAMES_TO_VIDEO) {
    if (params.startFrame) {
      generateVideoPayload.image = {
        imageBytes: params.startFrame.base64,
        mimeType: params.startFrame.file.type, 
      };
      log('Added Start Frame');
    }

    const finalEndFrame = params.isLooping ? params.startFrame : params.endFrame;
    if (finalEndFrame) {
      generateVideoPayload.config.lastFrame = {
        imageBytes: finalEndFrame.base64,
        mimeType: finalEndFrame.file.type,
      };
      log('Added End Frame');
    }
  } else if (params.mode === GenerationMode.REFERENCES_TO_VIDEO) {
    const referenceImagesPayload: VideoGenerationReferenceImage[] = [];
    if (params.referenceImages) {
      const validImages = params.referenceImages.filter(img => !!img);
      for (const img of validImages) {
        referenceImagesPayload.push({
          image: {
            imageBytes: img.base64,
            mimeType: img.file.type,
          },
          referenceType: VideoGenerationReferenceType.ASSET,
        });
      }
    }
    if (referenceImagesPayload.length > 0) {
      generateVideoPayload.config.referenceImages = referenceImagesPayload;
      log(`Added ${referenceImagesPayload.length} reference images`);
    }
  } else if (params.mode === GenerationMode.EXTEND_VIDEO) {
    if (params.inputVideoObject) {
      generateVideoPayload.video = params.inputVideoObject;
      log('Added Input Video for Extension');
    } else {
      throw new Error('An input video object is required to extend a video.');
    }
  }

  // DEBUG LOGGING
  const debugPayload = {
      model: generateVideoPayload.model,
      config: {
          ...generateVideoPayload.config,
      },
      prompt: generateVideoPayload.prompt?.substring(0, 50) + '...',
      hasImage: !!generateVideoPayload.image,
  };
  log('PAYLOAD DEBUG:', debugPayload);

  try {
    let operation = await ai.models.generateVideos(generateVideoPayload);
    log(`Operation Started. ID: ${operation.name}`);

    // POLLING LOOP
    const START_TIME = Date.now();
    const MAX_POLLING_TIME_MS = 10 * 60 * 1000; // 10 Minutes Timeout
    let attempt = 0;

    while (!operation.done) {
      if (Date.now() - START_TIME > MAX_POLLING_TIME_MS) {
          throw new Error("Video generation timed out (exceeded 10 minutes).");
      }

      attempt++;
      await new Promise((resolve) => setTimeout(resolve, 8000));
      log(`Polling Attempt #${attempt} (${Math.round((Date.now() - START_TIME)/1000)}s elapsed)...`);

      try {
        const newOp = await ai.operations.getVideosOperation({operation: operation});
        operation = newOp;
        if (operation.done) log('Operation reported DONE.', operation);
      } catch (pollError: any) {
        log(`Polling Error (retrying): ${pollError.message}`);
        // Check if we got a 404 on poll, which might mean the op is gone or we are using wrong client mode
      }
    }

    log('Processing Final Result...');

    if (operation.error) {
         const errorStr = JSON.stringify(operation.error);
         log(`API returned explicit Error: ${errorStr}`);

         if (errorStr.includes("guardrails") || errorStr.includes("safety") || errorStr.includes("third-party")) {
            throw new Error(`Generation Blocked by Safety Filters: ${operation.error.message}`);
         }
         throw new Error(`AI Operation Failed: ${operation.error.message}`);
    }

    const responseData = operation.response || (operation as any).result;

    if (responseData) {
      if (
        (responseData.raiMediaFilteredCount && responseData.raiMediaFilteredCount > 0) ||
        (responseData.rai_media_filtered_count && responseData.rai_media_filtered_count > 0)
      ) {
          const reasons = responseData.raiMediaFilteredReasons || responseData.rai_media_filtered_reasons || [];
          const reasonStr = reasons.length > 0 ? reasons.join(', ') : 'Safety Guardrails';
          log(`BLOCKED BY RAI: ${reasonStr}`);
          throw new Error(`Generation Blocked by Safety Filters: ${reasonStr}`);
      }

      const videos = responseData.generatedVideos || responseData.generated_videos;

      if (!videos || videos.length === 0) {
        throw new Error('AI reported success but returned no videos.');
      }

      const firstVideo = videos[0];
      const uri = firstVideo?.video?.uri || (firstVideo as any).gcsUri || (firstVideo as any).uri; 

      if (!uri) {
        throw new Error('Generated video object is missing a URI property.');
      }

      const videoObject = firstVideo.video || { uri: uri };
      const url = decodeURIComponent(uri);
      log(`Video URI: ${url}`);

      // Construct Fetch URL
      let fetchUrl = url;
      // If we are in Gemini API mode, the URL is likely generativelanguage.googleapis.com
      // We MUST append the API key.
      if (url.includes('googleapis.com')) {
         const separator = url.includes('?') ? '&' : '?';
         fetchUrl = `${url}${separator}key=${apiKey}`;
      }

      log(`Fetching Video from: ${fetchUrl.substring(0, 50)}...`);

      const res = await fetch(fetchUrl);
      if (!res.ok) {
        log(`Fetch failed: ${res.status} ${res.statusText}`);
        throw new Error(`Failed to download video: ${res.status} ${res.statusText}`);
      }

      const contentType = res.headers.get('content-type');
      if (contentType && !contentType.includes('video') && !contentType.includes('octet-stream')) {
         const textBody = await res.text();
         // Check for XML error (AccessDenied etc)
         if (textBody.includes('AccessDenied') || textBody.includes('error')) {
            throw new Error(`Access Denied to Video: ${textBody.substring(0, 100)}`);
         }
         log(`Warning: Content-Type is ${contentType}, but proceeding if body looks like video.`);
      }

      const videoBlob = await res.blob();
      log(`Blob received. Size: ${videoBlob.size} bytes. Type: ${videoBlob.type}`);

      if (videoBlob.size < 1000) {
         throw new Error(`Downloaded file is too small (${videoBlob.size} bytes). Likely an error text.`);
      }

      const objectUrl = URL.createObjectURL(videoBlob);
      return {objectUrl, blob: videoBlob, uri: url, video: videoObject, isSimulation: false};
    } else {
      throw new Error(`AI Operation Failed: No response data found`);
    }
  } catch (error: any) {
    log(`FATAL EXCEPTION: ${JSON.stringify(error)}`);
    throw error;
  }
};

