import React, {useRef, useState, useEffect} from 'react';
import {AspectRatio} from '../types';
import {ArrowPathIcon, DownloadIcon, SparklesIcon, AlertCircleIcon, PlayIcon} from './icons';

interface VideoResultProps {
  videoUrl: string;
  onRetry: () => void;
  onNewVideo: () => void;
  onExtend: () => void;
  canExtend: boolean;
  aspectRatio: AspectRatio;
}

const VideoResult: React.FC<VideoResultProps> = ({
  videoUrl,
  onRetry,
  onNewVideo,
  onExtend,
  canExtend,
  aspectRatio,
}) => {
  const isPortrait = aspectRatio === AspectRatio.PORTRAIT;
  const isSquare = aspectRatio === AspectRatio.SQUARE;

  const videoRef = useRef<HTMLVideoElement>(null);
  const [loadError, setLoadError] = useState(false);
  const [isBuffering, setIsBuffering] = useState(true);
  const [isPlaying, setIsPlaying] = useState(false);

  useEffect(() => {
      // Сброс состояний при смене URL
      setLoadError(false);
      setIsBuffering(true);
      setIsPlaying(false);
  }, [videoUrl]);

  return (
    <div className="w-full relative flex flex-col items-center p-1 animate-fade-in">

      {/* Back/New Button */}
      <div className="w-full flex justify-between items-center mb-6">
         <button onClick={onNewVideo} className="text-gray-400 hover:text-white flex items-center gap-2 text-sm transition-colors">
            ← Назад к редактору
         </button>
         <div className="text-sm text-green-400 font-medium flex items-center gap-2 bg-green-900/20 px-3 py-1 rounded-full border border-green-500/20">
            ✓ Генерация завершена
         </div>
      </div>

      {/* Video Container */}
      <div 
        className={`relative group w-full ${
          isPortrait ? 'max-w-sm aspect-[9/16]' : isSquare ? 'max-w-lg aspect-square' : 'max-w-4xl aspect-video'
        } bg-black rounded-2xl overflow-hidden border border-white/10 shadow-2xl flex items-center justify-center`}
      >
        {!loadError ? (
            <>
                {isBuffering && (
                    <div className="absolute inset-0 z-10 flex flex-col items-center justify-center bg-black/60 backdrop-blur-sm transition-opacity">
                        <div className="w-10 h-10 border-4 border-indigo-500/30 border-t-indigo-500 rounded-full animate-spin mb-3"></div>
                        <span className="text-xs text-indigo-300 font-medium">Загрузка плеера...</span>
                    </div>
                )}

                <video
                  ref={videoRef}
                  src={videoUrl}
                  controls
                  autoPlay
                  loop
                  playsInline
                  preload="auto"
                  className="w-full h-full object-contain"
                  onLoadedData={() => setIsBuffering(false)}
                  onPlaying={() => {
                      setIsBuffering(false);
                      setIsPlaying(true);
                  }}
                  onWaiting={() => setIsBuffering(true)}
                  onError={(e) => {
                      console.error("Video Playback Error", e);
                      setLoadError(true);
                      setIsBuffering(false);
                  }}
                />
            </>
        ) : (
            <div className="flex flex-col items-center justify-center p-8 text-center bg-[#121216] w-full h-full">
                <AlertCircleIcon className="w-12 h-12 text-red-500 mb-4" />
                <h3 className="text-lg font-bold text-white mb-2">Ошибка воспроизведения</h3>
                <p className="text-sm text-gray-400 max-w-md mb-6">
                    Видео сгенерировано, но браузер не может его воспроизвести. 
                    Возможно, формат (1080p) требует скачивания.
                </p>
                <a 
                    href={videoUrl} 
                    download="video_result.mp4"
                    className="px-6 py-3 bg-white text-black font-bold rounded-lg hover:bg-gray-200 transition-colors flex items-center gap-2"
                >
                    <DownloadIcon className="w-4 h-4" />
                    Скачать файл
                </a>
            </div>
        )}
      </div>

      {/* Action Bar */}
      <div className="mt-8 flex flex-wrap justify-center gap-4">

        <button
          onClick={onRetry}
          className="flex items-center gap-2 px-6 py-3 bg-[#1a1a1f] hover:bg-[#25252b] border border-white/10 text-white font-medium rounded-xl transition-all"
        >
          <ArrowPathIcon className="w-4 h-4" />
          Повторить
        </button>

        <a
          href={videoUrl}
          download="video_zavod_result.mp4"
          className="flex items-center gap-2 px-8 py-3 bg-white text-black hover:bg-gray-200 font-bold rounded-xl transition-all shadow-lg hover:shadow-xl hover:scale-105"
        >
          <DownloadIcon className="w-4 h-4" />
          Скачать MP4
        </a>

        {canExtend && !loadError && (
           <button
             onClick={onExtend}
             className="flex items-center gap-2 px-6 py-3 bg-violet-600/20 hover:bg-violet-600/30 text-violet-300 border border-violet-500/30 font-medium rounded-xl transition-all"
           >
             <SparklesIcon className="w-4 h-4" />
             Расширить (+5с)
           </button>
        )}

      </div>
    </div>
  );
};

