import React, { useState, useEffect } from 'react';
import { ActivityIcon, CheckCircleIcon, AlertCircleIcon, ArrowPathIcon } from './icons';

interface VideoDiagnosticsProps {
  videoUrl: string; // Blob URL
  originalUri?: string; // GCS URI
  apiKey?: string; // To reconstruct download link
  onClose: () => void;
}

const VideoDiagnostics: React.FC<VideoDiagnosticsProps> = ({ videoUrl, originalUri, apiKey, onClose }) => {
  const [status, setStatus] = useState<'idle' | 'checking' | 'done'>('idle');
  const [report, setReport] = useState<any>({});

  const runDiagnostics = async () => {
    setStatus('checking');
    const r: any = {};

    // 1. Check Blob URL
    r.blobUrl = videoUrl;
    try {
        const blobReq = await fetch(videoUrl);
        const blob = await blobReq.blob();
        r.blobSize = blob.size;
        r.blobType = blob.type;
        r.blobStatus = 'OK';

        if (blob.size < 1000) {
            r.blobWarning = "Файл подозрительно маленький (<1KB). Возможно, это текстовая ошибка.";
            r.contentSnippet = await blob.slice(0, 200).text();
        }
    } catch (e: any) {
        r.blobStatus = `ERROR: ${e.message}`;
    }

    // 2. Check Original GCS URI (if available)
    if (originalUri) {
        r.originalUri = originalUri;
        const cleanKey = apiKey?.trim().replace(/["']/g, '');
        const downloadUrl = originalUri.includes('key=') 
            ? originalUri 
            : `${originalUri}${originalUri.includes('?') ? '&' : '?'}key=${cleanKey}`;

        r.downloadUrl = downloadUrl;

        try {
            const headReq = await fetch(downloadUrl, { method: 'HEAD' });
            r.gcsStatus = headReq.status;
            r.gcsContentType = headReq.headers.get('content-type');
            r.gcsContentLength = headReq.headers.get('content-length');

            if (!headReq.ok) {
                // Try GET to see error body
                 const getReq = await fetch(downloadUrl);
                 const text = await getReq.text();
                 r.gcsErrorBody = text.slice(0, 300);
            }
        } catch (e: any) {
            r.gcsNetworkError = e.message;
        }
    }

    setReport(r);
    setStatus('done');
  };

  useEffect(() => {
    runDiagnostics();
  }, []);

  return (
    <div className="bg-[#1a1a20] border border-white/10 rounded-xl p-4 mt-4 text-sm font-mono text-gray-300 w-full animate-fade-in">
        <div className="flex justify-between items-center mb-3 pb-2 border-b border-white/5">
            <h3 className="font-bold text-white flex items-center gap-2">
                <ActivityIcon className="w-4 h-4 text-amber-500" />
                Модуль Диагностики Видео
            </h3>
            <button onClick={onClose} className="text-gray-500 hover:text-white">Закрыть</button>
        </div>

        {status === 'checking' && (
            <div className="flex items-center gap-2 text-indigo-400 py-4">
                <ArrowPathIcon className="w-4 h-4 animate-spin" />
                Сканирование файла и заголовков...
            </div>
        )}

        {status === 'done' && (
            <div className="space-y-3">
                <div className="grid grid-cols-[120px_1fr] gap-2">
                    <span className="text-gray-500">Blob Size:</span>
                    <span className={report.blobSize < 2000 ? 'text-red-400 font-bold' : 'text-green-400'}>
                        {report.blobSize ? `${(report.blobSize / 1024).toFixed(2)} KB` : 'N/A'}
                    </span>

                    <span className="text-gray-500">MIME Type:</span>
                    <span className={report.blobType !== 'video/mp4' ? 'text-amber-400' : 'text-green-400'}>
                        {report.blobType || 'Unknown'}
                    </span>

                    <span className="text-gray-500">GCS Status:</span>
                    <span className={report.gcsStatus !== 200 ? 'text-red-400 font-bold' : 'text-green-400'}>
                        {report.gcsStatus || 'Untested'}
                    </span>
                </div>

                {report.blobWarning && (
                    <div className="p-2 bg-red-900/20 border border-red-500/30 rounded text-red-300 text-xs">
                        <strong>Внимание:</strong> {report.blobWarning}
                        <div className="mt-1 opacity-70 italic border-l-2 border-red-500 pl-2">
                            "{report.contentSnippet}"
                        </div>
                    </div>
                )}

                {report.gcsErrorBody && (
                    <div className="p-2 bg-amber-900/20 border border-amber-500/30 rounded text-amber-300 text-xs break-all">
                        <strong>Ответ сервера (GCS Error):</strong>
                        <div className="mt-1 font-mono text-[10px]">
                            {report.gcsErrorBody}
                        </div>
                    </div>
                )}

                <div className="pt-2 border-t border-white/5 flex gap-2">
                     <button 
                       onClick={runDiagnostics} 
                       className="px-3 py-1.5 bg-white/5 hover:bg-white/10 rounded text-xs flex items-center gap-2"
                     >
                        <ArrowPathIcon className="w-3 h-3" /> Повторить тест
                     </button>
                     {report.originalUri && (
                         <a 
                            href={report.downloadUrl} 
                            target="_blank" 
                            rel="noreferrer"
                            className="px-3 py-1.5 bg-indigo-500/20 hover:bg-indigo-500/30 text-indigo-300 rounded text-xs"
                         >
                            Открыть прямую ссылку (Debug)
                         </a>
                     )}
                </div>
            </div>
        )}
    </div>
  );
};

