import {
  GoogleGenAI,
  Video,
  VideoGenerationReferenceImage,
  VideoGenerationReferenceType,
  HarmCategory,
  HarmBlockThreshold,
  GenerateContentResponse
} from '@google/genai';
import {GenerateVideoParams, GeneratePhotoParams, GenerationMode, VertexConnectionConfig, VeoModel, PhotoModel, Resolution, AspectRatio} from '../types';

// Очистка ключа от лишних символов (пробелы, кавычки)
const getCleanApiKey = (overriddenKey?: string) => {
  let apiKey = overriddenKey || process.env.API_KEY || '';
  return apiKey.trim().replace(/["']/g, '');
}

// Проверка сигнатуры MP4 (ftyp)
const isValidMp4 = async (blob: Blob): Promise<boolean> => {
    if (blob.size < 1000) return false;
    try {
        const buffer = await blob.slice(0, 12).arrayBuffer();
        const view = new Uint8Array(buffer);
        // MP4 обычно содержит 'ftyp' начиная с 4-го байта
        // 0x66='f', 0x74='t', 0x79='y', 0x70='p'
        if (view[4] === 0x66 && view[5] === 0x74 && view[6] === 0x79 && view[7] === 0x70) {
            return true;
        }
        // Некоторые потоки могут начинаться иначе, но для Veo это стандарт
        return false;
    } catch {
        return false;
    }
};

