  aspectRatio: AspectRatio;
}

const VideoResult: React.FC<VideoResultProps> = ({
  videoUrl,
  onRetry,
  onNewVideo,
  onExtend,
  canExtend,
  aspectRatio,
}) => {
  const isPortrait = aspectRatio === AspectRatio.PORTRAIT;
  const isSquare = aspectRatio === AspectRatio.SQUARE;

  const videoRef = useRef<HTMLVideoElement>(null);
  const [loadError, setLoadError] = useState(false);
  const [isBuffering, setIsBuffering] = useState(true);
  const [isPlaying, setIsPlaying] = useState(false);
  const [showDiagnostics, setShowDiagnostics] = useState(false);
  const [isStalled, setIsStalled] = useState(false);

  useEffect(() => {
      // Сброс состояний при смене URL
      setLoadError(false);
      setIsBuffering(true);
      setIsPlaying(false);
      setIsStalled(false);
      setShowDiagnostics(false);

      // Watchdog для обнаружения "черного экрана" (когда видео не начинает играть)
      const timeout = setTimeout(() => {
          if (videoRef.current && videoRef.current.currentTime === 0 && !loadError) {
              console.warn("Video Playback Stall Detected");
              setIsStalled(true);
              setIsBuffering(false);
          }
      }, 7000); // Если через 7 сек не пошло

      return () => clearTimeout(timeout);
  }, [videoUrl]);

  return (
    <div className="w-full relative flex flex-col items-center p-1 animate-fade-in">

      {/* Back/New Button */}
      <div className="w-full flex justify-between items-center mb-6">
         <button onClick={onNewVideo} className="text-gray-400 hover:text-white flex items-center gap-2 text-sm transition-colors">
            ← Назад к редактору
         </button>
         <div className="flex gap-2">
             <button 
                onClick={() => setShowDiagnostics(!showDiagnostics)}
                className={`text-xs flex items-center gap-1 px-3 py-1 rounded-full border transition-colors ${showDiagnostics ? 'bg-amber-500/20 text-amber-400 border-amber-500/30' : 'bg-white/5 text-gray-500 border-white/10 hover:text-white'}`}
             >
                <ActivityIcon className="w-3 h-3" />
                {showDiagnostics ? 'Скрыть диагностику' : 'Диагностика'}
             </button>
             <div className="text-sm text-green-400 font-medium flex items-center gap-2 bg-green-900/20 px-3 py-1 rounded-full border border-green-500/20">
                ✓ Генерация завершена
             </div>
         </div>
      </div>

      {(showDiagnostics || isStalled) && (
          <div className="w-full max-w-4xl mb-6 animate-fade-in">
             {isStalled && !showDiagnostics && (
                 <div className="mb-2 p-3 bg-amber-900/20 border border-amber-500/30 rounded-lg flex items-center gap-3 text-amber-200 text-sm">
                     <AlertCircleIcon className="w-5 h-5" />
                     <span>Кажется, видео зависло или не воспроизводится. Попробуйте диагностику или скачивание.</span>
                 </div>
             )}
             <VideoDiagnostics 
                videoUrl={videoUrl} 
                onClose={() => setShowDiagnostics(false)}
             />
          </div>
      )}

      {/* Video Container */}
      <div 
        className={`relative group w-full ${
          isPortrait ? 'max-w-sm aspect-[9/16]' : isSquare ? 'max-w-lg aspect-square' : 'max-w-4xl aspect-video'
        } bg-black rounded-2xl overflow-hidden border border-white/10 shadow-2xl flex items-center justify-center`}
      >
        {!loadError ? (
            <>
                {(isBuffering || (isStalled && !isPlaying)) && (
                    <div className="absolute inset-0 z-10 flex flex-col items-center justify-center bg-black/60 backdrop-blur-sm transition-opacity pointer-events-none">
                        <div className="w-10 h-10 border-4 border-indigo-500/30 border-t-indigo-500 rounded-full animate-spin mb-3"></div>
                        <span className="text-xs text-indigo-300 font-medium">
                            {isStalled ? 'Ожидание данных...' : 'Буферизация видео...'}
                        </span>
                    </div>
                )}

                <video
                  ref={videoRef}
                  src={videoUrl}
                  controls
                  autoPlay
                  loop
                  playsInline
                  preload="auto"
                  crossOrigin="anonymous"
                  className="w-full h-full object-contain bg-[#050505]"
                  onLoadedData={() => {
                      setIsBuffering(false);
                      setIsStalled(false);
                  }}
                  onPlaying={() => {
                      setIsBuffering(false);
                      setIsPlaying(true);
                      setIsStalled(false);
                  }}
                  onWaiting={() => setIsBuffering(true)}
                  onStalled={() => {
                      setIsStalled(true);
                  }}
                  onError={(e) => {
                      console.error("Video Playback Error", e);
                      setLoadError(true);
                      setIsBuffering(false);
                      setShowDiagnostics(true); 
                  }}
                />
            </>
        ) : (
            <div className="flex flex-col items-center justify-center p-8 text-center bg-[#121216] w-full h-full">
                <AlertCircleIcon className="w-12 h-12 text-red-500 mb-4" />
                <h3 className="text-lg font-bold text-white mb-2">Ошибка плеера</h3>
                <p className="text-sm text-gray-400 max-w-md mb-6">
                    Браузер не может воспроизвести этот файл. <br/>
                    Возможно, файл поврежден или формат (1080p) слишком тяжелый.
                </p>
                <div className="flex gap-3">
                    <button 
                        onClick={() => setShowDiagnostics(true)}
                        className="px-4 py-2 bg-white/10 text-white rounded-lg hover:bg-white/20 transition-colors text-sm"
                    >
                        Открыть диагностику
