          className="flex items-center gap-2 px-6 py-3 bg-[#1a1a1f] hover:bg-[#25252b] border border-white/10 text-white font-medium rounded-xl transition-all"
        >
          <ArrowPathIcon className="w-4 h-4" />
          Повторить
        </button>

        <a
          href={videoUrl}
          download="video_zavod_result.mp4"
          className="flex items-center gap-2 px-8 py-3 bg-white text-black hover:bg-gray-200 font-bold rounded-xl transition-all shadow-lg hover:shadow-xl hover:scale-105"
        >
          <DownloadIcon className="w-4 h-4" />
          Скачать MP4
        </a>

        {canExtend && !loadError && (
           <button
             onClick={onExtend}
             className="flex items-center gap-2 px-6 py-3 bg-violet-600/20 hover:bg-violet-600/30 text-violet-300 border border-violet-500/30 font-medium rounded-xl transition-all"
           >
             <SparklesIcon className="w-4 h-4" />
             Расширить (+5с)
           </button>
        )}

      </div>
    </div>
  );
};

