import {
  GoogleGenAI,
  Video,
  VideoGenerationReferenceImage,
  VideoGenerationReferenceType,
  HarmCategory,
  HarmBlockThreshold,
  GenerateContentResponse
} from '@google/genai';
import {GenerateVideoParams, GeneratePhotoParams, GenerationMode, VertexConnectionConfig, VeoModel, PhotoModel, Resolution, AspectRatio} from '../types';

// Очистка ключа от лишних символов (пробелы, кавычки)
const getCleanApiKey = (overriddenKey?: string) => {
  let apiKey = overriddenKey || process.env.API_KEY || '';
  return apiKey.trim().replace(/["']/g, '');
}

// Проверка сигнатуры MP4 (ftyp) - Базовая проверка заголовка
const isValidMp4Header = async (blob: Blob): Promise<boolean> => {
    if (blob.size < 1000) return false;
    try {
        const buffer = await blob.slice(0, 12).arrayBuffer();
        const view = new Uint8Array(buffer);
        // MP4 обычно содержит 'ftyp' начиная с 4-го байта
        if (view[4] === 0x66 && view[5] === 0x74 && view[6] === 0x79 && view[7] === 0x70) {
            return true;
        }
        return false;
    } catch {
        return false;
    }
};

// ПОЛНАЯ ПРОВЕРКА ВОСПРОИЗВОДИМОСТИ (Browser Integrity Check)
// Создает невидимый элемент видео и пытается загрузить метаданные.
// Если это не удается, файл считается битым, даже если заголовки верны.
const isPlayableVideo = async (blob: Blob): Promise<{playable: boolean; error?: string}> => {
    return new Promise((resolve) => {
        const video = document.createElement('video');
        video.preload = 'metadata';
        video.onloadedmetadata = () => {
             window.URL.revokeObjectURL(video.src);
             resolve({ playable: true });
        };
        video.onerror = () => {
             const err = video.error;
             let msg = "Unknown Error";
             if (err) {
                 switch (err.code) {
                     case 1: msg = "MEDIA_ERR_ABORTED"; break;
                     case 2: msg = "MEDIA_ERR_NETWORK"; break;
                     case 3: msg = "MEDIA_ERR_DECODE"; break;
                     case 4: msg = "MEDIA_ERR_SRC_NOT_SUPPORTED"; break;
                 }
                 msg += ` (${err.message})`;
             }
             window.URL.revokeObjectURL(video.src);
             resolve({ playable: false, error: msg });
        };
        video.src = window.URL.createObjectURL(blob);
    });
}

