export const generateImage = async (
  params: GeneratePhotoParams,
  connectionConfig: VertexConnectionConfig,
  onLog?: (message: string, data?: any) => void
): Promise<{imageUrl: string; blob: Blob}> => {
  const log = (msg: string, data?: any) => {
      console.log(`[Photo] ${msg}`, data || '');
      if (onLog) onLog(msg, data);
  };

  const apiKey = getCleanApiKey(connectionConfig.apiKey);
  const ai = new GoogleGenAI({ apiKey });

  log('Запуск генерации фото (Nano Banana)...');

  try {
    const response: GenerateContentResponse = await ai.models.generateContent({
      model: params.model,
      contents: {
        parts: [
          ...(params.referenceImages?.map(img => ({
            inlineData: { data: img.base64, mimeType: img.file.type }
          })) || []),
          { text: params.prompt }
        ]
      },
      config: {
        imageConfig: {
          aspectRatio: params.aspectRatio,
          ...(params.model === PhotoModel.NANO_BANANA_PRO ? {
              imageSize: params.quality === '4K' ? '4096' : '1024'
          } : {})
        }
      }
    });

    let base64Image: string | undefined;
    let mimeType: string = 'image/png';

    const parts = response.candidates?.[0]?.content?.parts || [];
    for (const part of parts) {
      if (part.inlineData) {
        base64Image = part.inlineData.data;
        mimeType = part.inlineData.mimeType || 'image/png';
        break;
      }
    }

    if (!base64Image) throw new Error("API не вернул данные изображения.");

    const byteCharacters = atob(base64Image);
    const byteNumbers = new Array(byteCharacters.length);
    for (let i = 0; i < byteCharacters.length; i++) {
      byteNumbers[i] = byteCharacters.charCodeAt(i);
    }
    const blob = new Blob([new Uint8Array(byteNumbers)], { type: mimeType });
    return { imageUrl: URL.createObjectURL(blob), blob };

  } catch (error: any) {
    log(`Ошибка фото-генерации: ${error.message}`, 'error');
    throw error;
  }
};

export const generateVideo = async (
  params: GenerateVideoParams,
  connectionConfig: VertexConnectionConfig,
  onLog?: (message: string, data?: any) => void
): Promise<{objectUrl: string; blob: Blob; uri: string; video: Video; isSimulation?: boolean}> => {
  const log = (msg: string, data?: any) => {
      console.log(`[Video] ${msg}`, data || '');
      if (onLog) onLog(msg, data);
  };

  const apiKey = getCleanApiKey(connectionConfig.apiKey);
  const ai = new GoogleGenAI({ apiKey });

  log('Инициализация Veo Video Generation...');

  // 1. Настройка модели и параметров
  let effectiveModel = params.model;
  const isHighRes = params.resolution === Resolution.P1080;

  // === 1080p ENFORCEMENT ===
  if (isHighRes) {
      if (effectiveModel !== VeoModel.VEO) {
          log('Upgrade: Авто-переключение на Veo Pro (требуется для 1080p)');
          effectiveModel = VeoModel.VEO;
      }
  }
  if (params.mode === GenerationMode.REFERENCES_TO_VIDEO) {
      effectiveModel = VeoModel.VEO;
  }

  const durationSec = parseInt(params.duration || '5', 10);

  const payload: any = {
    model: effectiveModel,
    prompt: params.prompt || "Cinematic motion, high quality",
    config: {
      numberOfVideos: 1,
      resolution: params.resolution || '720p',
      aspectRatio: params.aspectRatio || '16:9',
      durationSeconds: durationSec
    }
  };

  if (params.mode === GenerationMode.FRAMES_TO_VIDEO && params.startFrame) {
    payload.image = {
      imageBytes: params.startFrame.base64,
      mimeType: params.startFrame.file.type
    };
    if (params.endFrame) {
      payload.config.lastFrame = {
        imageBytes: params.endFrame.base64,
        mimeType: params.endFrame.file.type
      };
    }
  } else if (params.mode === GenerationMode.REFERENCES_TO_VIDEO && params.referenceImages) {
    payload.config.referenceImages = params.referenceImages.map(img => ({
      image: { imageBytes: img.base64, mimeType: img.file.type },
      referenceType: VideoGenerationReferenceType.ASSET
    }));
  }

  try {
    log(`Start API Request: Model=${effectiveModel}, Res=${payload.config.resolution}, Ratio=${payload.config.aspectRatio}`);

    let operation = await ai.models.generateVideos(payload);
    log(`LRO Started: ${operation.name}`);

    // 3. Цикл ожидания
    const startTime = Date.now();
    // Увеличиваем таймауты для 1080p, т.к. рендеринг тяжелее
    const timeoutMs = isHighRes ? 25 * 60 * 1000 : 10 * 60 * 1000;
    const pollInterval = isHighRes ? 20000 : 10000;

    while (!operation.done) {
      if (Date.now() - startTime > timeoutMs) throw new Error("Timeout: Генерация заняла слишком много времени.");
      await new Promise(r => setTimeout(r, pollInterval));
      const elapsed = Math.round((Date.now() - startTime) / 1000);
      log(`Генерация в облаке... (${elapsed}s)`);
      const newOp = await ai.operations.getVideosOperation({ operation });
      operation = newOp;
    }

    if (operation.error) {
        log(`API Error: ${JSON.stringify(operation.error)}`, 'error');
        throw new Error(operation.error.message || "Unknown API Error");
    }

    const response = operation.response || (operation as any).result;
    if (!response) throw new Error("Empty Response from API");

    const videos = response.generatedVideos || response.generated_videos;
    if (!videos || videos.length === 0) {
        if (response.raiMediaFilteredCount > 0) throw new Error("Safety Filter Blocked the content.");
        throw new Error("No video found in response.");
    }

    const resultVideo = videos[0];
    const videoUri = resultVideo.video?.uri || resultVideo.uri;

    if (!videoUri) throw new Error("API did not return a video URI.");

    log(`Video URI obtained: ${videoUri}`);

    // 5. ROBUST DOWNLOAD & INTEGRITY CHECK
    const downloadUrl = videoUri.includes('key=') ? videoUri : `${videoUri}${videoUri.includes('?') ? '&' : '?'}key=${apiKey}`;

    // Стабилизация. Для 1080p критически важно ждать дольше.
    // Файл может быть "доступен" по HTTP (200 OK), но быть неполным (0 bytes или partial).
    const stabilityWait = isHighRes ? 10000 : 4000;
    log(`Waiting for file propagation (${stabilityWait / 1000}s)...`);
    await new Promise(r => setTimeout(r, stabilityWait));

    let attempt = 0;
    const MAX_RETRIES = 5;
    let finalBlob: Blob | null = null;

    while (attempt < MAX_RETRIES) {
        try {
            log(`Downloading... (Attempt ${attempt + 1}/${MAX_RETRIES})`);
            const fetchResponse = await fetch(downloadUrl);

            if (!fetchResponse.ok) {
                 if (fetchResponse.status === 404 || fetchResponse.status === 403) {
                     log(`File not ready (HTTP ${fetchResponse.status})...`);
                 } else {
                     throw new Error(`HTTP Error ${fetchResponse.status}`);
                 }
            } else {
                // Check Content-Type
                const contentType = fetchResponse.headers.get('content-type');
                if (contentType && (contentType.includes('xml') || contentType.includes('html'))) {
                    const errText = await fetchResponse.text();
                    log(`Received XML error instead of video: ${errText.substring(0, 50)}...`, 'error');
                    throw new Error("Invalid Content-Type (XML/HTML)");
                }

                const blob = await fetchResponse.blob();

                // 1. Size Check
                const minSize = isHighRes ? 500 * 1024 : 50 * 1024; // 1080p MUST be > 500KB usually
                if (blob.size < minSize) {
                     log(`File too small (${blob.size} bytes). Likely incomplete.`);
                     throw new Error("File incomplete (size too small)");
                }

                // 2. Header Check
                const hasHeader = await isValidMp4Header(blob);
                if (!hasHeader) {
                    log("Invalid MP4 Header (Magic Bytes mismatch).");
                    throw new Error("Corrupt File Header");
                }

                // 3. Playability Check (The "Black Screen" killer)
                log("Verifying video integrity...");
                const check = await isPlayableVideo(blob);
                if (!check.playable) {
                    log(`Video integrity failed: ${check.error}`);
                    throw new Error(`Integrity Check Failed: ${check.error}`);
                }

                finalBlob = blob;
                log("Integrity Check Passed!");
                break; // Success
            }

        } catch (e: any) {
            log(`Download/Check failed: ${e.message}`, 'error');
        }

        attempt++;
        if (attempt < MAX_RETRIES) {
            // Exponential backoff
            const waitTime = 5000 + (attempt * 3000);
            log(`Retrying in ${waitTime/1000}s...`);
            await new Promise(r => setTimeout(r, waitTime));
        }
    }

    if (!finalBlob) {
        throw new Error("Failed to download a playable video file after multiple attempts. The file at the URI might be corrupt or inaccessible.");
    }

    log(`Success! Final size: ${(finalBlob.size / 1024 / 1024).toFixed(2)} MB`);
    const objectUrl = URL.createObjectURL(finalBlob);

    return {
      objectUrl,
      blob: finalBlob,
      uri: videoUri,
      video: resultVideo.video || resultVideo,
      isSimulation: false
    };

  } catch (error: any) {
    log(`Critical Error: ${error.message}`, 'error');
    throw error;
  }
};

