import React, { useState, useEffect } from 'react';
import { ActivityIcon, CheckCircleIcon, AlertCircleIcon, ArrowPathIcon } from './icons';

interface VideoDiagnosticsProps {
  videoUrl: string; // Blob URL
  onClose: () => void;
  lastError?: MediaError | null; // Pass actual video element error
}

const VideoDiagnostics: React.FC<VideoDiagnosticsProps> = ({ videoUrl, onClose, lastError }) => {
  const [status, setStatus] = useState<'idle' | 'checking' | 'done'>('idle');
  const [report, setReport] = useState<any>({});

  const getMediaErrorMessage = (code: number) => {
      switch (code) {
          case 1: return "MEDIA_ERR_ABORTED: Загрузка прервана пользователем.";
          case 2: return "MEDIA_ERR_NETWORK: Сетевая ошибка при загрузке.";
          case 3: return "MEDIA_ERR_DECODE: Ошибка декодирования. Файл поврежден или кодек не поддерживается.";
          case 4: return "MEDIA_ERR_SRC_NOT_SUPPORTED: Формат файла не поддерживается этим браузером.";
          default: return `Unknown Code (${code})`;
      }
  };

  const runDiagnostics = async () => {
    setStatus('checking');
    const r: any = {};

    // 0. Previous Error Info
    if (lastError) {
        r.lastErrorCode = lastError.code;
        r.lastErrorMsg = lastError.message;
        r.lastErrorHuman = getMediaErrorMessage(lastError.code);
    }

    // 1. Check Blob URL
    r.blobUrl = videoUrl;
    try {
        const blobReq = await fetch(videoUrl);
        const blob = await blobReq.blob();
        r.blobSize = blob.size;
        r.blobType = blob.type;

        if (blob.size < 50000) {
             r.blobWarning = "Critical: File is extremely small (<50KB). Usually indicates a text error file.";
             r.contentSnippet = await blob.slice(0, 200).text();
        } else {
            // Magic Bytes Check
            const buffer = await blob.slice(0, 8).arrayBuffer();
            const view = new Uint8Array(buffer);
            r.magicBytes = Array.from(view).map(b => b.toString(16).padStart(2, '0')).join(' ');

            // ftyp check
            const isFtyp = view[4] === 0x66 && view[5] === 0x74 && view[6] === 0x79 && view[7] === 0x70;
            r.isMp4Signature = isFtyp;

            if (!isFtyp) {
                r.blobWarning = "Critical: Invalid File Header. Not a valid MP4 container.";
            }
        }

    } catch (e: any) {
        r.blobStatus = `Fetch Error: ${e.message}`;
    }

    setReport(r);
    setStatus('done');
  };

  useEffect(() => {
    runDiagnostics();
  }, []);

  return (
    <div className="bg-[#1a1a20] border border-white/10 rounded-xl p-4 mt-4 text-sm font-mono text-gray-300 w-full animate-fade-in shadow-2xl">
        <div className="flex justify-between items-center mb-3 pb-2 border-b border-white/5">
            <h3 className="font-bold text-white flex items-center gap-2">
                <ActivityIcon className="w-4 h-4 text-amber-500" />
                Диагностика Ошибки (Black Screen Fix)
            </h3>
            <button onClick={onClose} className="text-gray-500 hover:text-white">Закрыть</button>
        </div>

        {status === 'checking' && (
            <div className="flex items-center gap-2 text-indigo-400 py-4">
                <ArrowPathIcon className="w-4 h-4 animate-spin" />
                Анализ файла...
            </div>
        )}

        {status === 'done' && (
            <div className="space-y-4">

                {/* Error from Video Tag */}
                {report.lastErrorCode && (
                    <div className="p-3 bg-red-900/20 border border-red-500/30 rounded text-red-300">
                        <strong className="block mb-1 text-red-200">Ошибка Плеера:</strong>
                        {report.lastErrorHuman}
                    </div>
                )}

                <div className="grid grid-cols-[140px_1fr] gap-2 text-xs">
                    <span className="text-gray-500">Blob Size:</span>
                    <span className={report.blobSize < 500000 ? 'text-amber-400 font-bold' : 'text-green-400'}>
                        {report.blobSize ? `${(report.blobSize / 1024 / 1024).toFixed(2)} MB` : 'N/A'}
                    </span>

                    <span className="text-gray-500">MIME Type:</span>
                    <span className={report.blobType !== 'video/mp4' ? 'text-amber-400' : 'text-green-400'}>
                        {report.blobType || 'Unknown'}
                    </span>

                    <span className="text-gray-500">Magic Bytes:</span>
                    <span className={report.isMp4Signature ? 'text-green-400' : 'text-red-400 font-bold'}>
                        {report.isMp4Signature ? 'OK (ftyp)' : `FAIL [${report.magicBytes}]`}
                    </span>
                </div>

                {report.blobWarning && (
                    <div className="p-3 bg-amber-900/20 border border-amber-500/30 rounded text-amber-300 text-xs mt-2">
                        <strong>Анализ Файла:</strong> {report.blobWarning}
                        {report.contentSnippet && (
                            <div className="mt-2 p-2 bg-black/30 rounded font-mono text-[10px] text-gray-400 break-all">
                                Начало файла: "{report.contentSnippet}"
                            </div>
                        )}
                    </div>
                )}

                <div className="pt-3 border-t border-white/5 flex gap-2">
                     <button 
                       onClick={runDiagnostics} 
                       className="px-3 py-1.5 bg-white/5 hover:bg-white/10 rounded text-xs flex items-center gap-2"
                     >
                        <ArrowPathIcon className="w-3 h-3" /> Re-scan
                     </button>
                     <a 
                        href={videoUrl} 
                        download="debug_video.mp4"
                        className="px-3 py-1.5 bg-indigo-500/20 hover:bg-indigo-500/30 text-indigo-300 rounded text-xs flex items-center gap-2"
                     >
                         Сохранить файл для поддержки
                     </a>
                </div>
            </div>
        )}
    </div>
  );
};

