import {
  GoogleGenAI,
  Video,
  VideoGenerationReferenceImage,
  VideoGenerationReferenceType,
  HarmCategory,
  HarmBlockThreshold,
  GenerateContentResponse
} from '@google/genai';
import {GenerateVideoParams, GeneratePhotoParams, GenerationMode, VertexConnectionConfig, VeoModel, PhotoModel, Resolution, AspectRatio} from '../types';

const getCleanApiKey = (overriddenKey?: string) => {
  let apiKey = overriddenKey || process.env.API_KEY || '';
  return apiKey.trim().replace(/["']/g, '');
}

// Ультра-валидатор MP4 для тяжелых файлов (1080p)
const isVideoStructurallySound = async (blob: Blob): Promise<{ok: boolean; error?: string}> => {
    if (blob.size < 1024 * 50) return {ok: false, error: "Файл слишком мал для видео 1080p"};

    try {
        // Проверяем наличие ftyp и moov атомов (важно для стриминга в плеере)
        const header = await blob.slice(0, 100).arrayBuffer();
        const headerView = new Uint8Array(header);
        const hasFtyp = headerView[4] === 102 && headerView[5] === 116 && headerView[6] === 121 && headerView[7] === 112; // 'ftyp'

        if (!hasFtyp) return {ok: false, error: "Неверный заголовок контейнера (not ftyp)"};

        return new Promise((resolve) => {
            const video = document.createElement('video');
            video.preload = 'metadata';
            video.onloadedmetadata = () => {
                const duration = video.duration;
                window.URL.revokeObjectURL(video.src);
                if (isNaN(duration) || duration === 0) resolve({ok: false, error: "Нулевая длительность видео"});
                else resolve({ok: true});
            };
            video.onerror = () => {
                const err = video.error;
                window.URL.revokeObjectURL(video.src);
                resolve({ok: false, error: `MediaError: ${err?.message || 'Decode failed'}`});
            };
            video.src = window.URL.createObjectURL(blob);
        });
    } catch (e: any) {
        return {ok: false, error: e.message};
    }
}

export const generateVideo = async (
  params: GenerateVideoParams,
  connectionConfig: VertexConnectionConfig,
  onLog?: (message: string, data?: any) => void
): Promise<{objectUrl: string; blob: Blob; uri: string; video: Video; isSimulation?: boolean}> => {
  const log = (msg: string, data?: any) => {
      console.log(`[Veo-Expert-Debug] ${msg}`, data || '');
      if (onLog) onLog(msg, data);
  };

  const apiKey = getCleanApiKey(connectionConfig.apiKey);
  const ai = new GoogleGenAI({ apiKey });

  // 1. ПРОВЕРКА ПАРАМЕТРОВ (Expert Guard)
  let modelToUse = params.model;
  const is1080p = params.resolution === Resolution.P1080;
  const isLong = parseInt(params.duration || '5') > 5;

  if (is1080p || isLong) {
      log('Конфигурация "High-Load": принудительное использование Veo Pro');
      modelToUse = VeoModel.VEO; // Только Pro тянет 1080p и 8 секунд стабильно
  }

  const payload: any = {
    model: modelToUse,
    prompt: params.prompt,
    config: {
      numberOfVideos: 1,
      resolution: params.resolution,
      aspectRatio: params.aspectRatio,
      durationSeconds: parseInt(params.duration || '5')
    }
  };

  // Обработка фреймов
  if (params.mode === GenerationMode.FRAMES_TO_VIDEO && params.startFrame) {
      payload.image = { imageBytes: params.startFrame.base64, mimeType: params.startFrame.file.type };
      if (params.endFrame) {
          payload.config.lastFrame = { imageBytes: params.endFrame.base64, mimeType: params.endFrame.file.type };
      }
  }

  try {
    log(`Запуск LRO: ${modelToUse} @ ${params.resolution}`);
    let operation = await ai.models.generateVideos(payload);

    const startTime = Date.now();
    const maxWait = 15 * 60 * 1000; // 15 минут для 1080p/8s

    while (!operation.done) {
      if (Date.now() - startTime > maxWait) throw new Error("Превышено время ожидания (15 мин).");
      await new Promise(r => setTimeout(r, 15000));
      log(`Генерация в процессе... (${Math.round((Date.now() - startTime)/1000)}с)`);
      operation = await ai.operations.getVideosOperation({ operation });
    }

    if (operation.error) {
        // ОБРАБОТКА ОШИБОК АВТОРИЗАЦИИ
        if (operation.error.code === 403 || operation.error.message?.includes('permission')) {
            throw new Error("PERMISSION_DENIED: Требуется проект с включенным биллингом (Paid Project) для модели Veo.");
        }
        throw new Error(operation.error.message || "Ошибка API");
    }

    const videoResult = (operation.response?.generatedVideos || (operation as any).result?.generated_videos)?.[0];
    const videoUri = videoResult?.video?.uri || videoResult?.uri;

    if (!videoUri) throw new Error("API не вернуло URI видео.");

    // СКАЧИВАНИЕ С ПОВТОРНЫМИ ПОПЫТКАМИ
    const downloadUrl = `${videoUri}${videoUri.includes('?') ? '&' : '?'}key=${apiKey}`;
    log('Видео создано. Начинаем загрузку и проверку целостности...');

    let attempt = 0;
    while (attempt < 5) {
        try {
            const resp = await fetch(downloadUrl);
            if (!resp.ok) throw new Error(`HTTP ${resp.status}`);

            const blob = await resp.blob();
            const check = await isVideoStructurallySound(blob);

            if (check.ok) {
                log('Проверка целостности пройдена успешно.');
                return {
                    objectUrl: URL.createObjectURL(blob),
                    blob,
                    uri: videoUri,
                    video: videoResult.video || videoResult
                };
            } else {
                log(`Файл поврежден: ${check.error}. Повтор...`);
            }
        } catch (e) {
            log(`Ошибка загрузки: ${e.message}`);
        }
        attempt++;
        await new Promise(r => setTimeout(r, 5000 * attempt));
    }

    throw new Error("Не удалось получить валидный видеофайл после 5 попыток. Попробуйте 720p.");

  } catch (error: any) {
    log(`Критическая ошибка: ${error.message}`, 'error');
    throw error;
  }
};

