export const generateImage = async (params: any, config: any, onLog: any) => {
    // Базовая реализация для сохранения работоспособности
    const ai = new GoogleGenAI({ apiKey: getCleanApiKey(config.apiKey) });
    const response = await ai.models.generateContent({
        model: params.model,
        contents: { parts: [{ text: params.prompt }] },
        config: { imageConfig: { aspectRatio: params.aspectRatio } }
    });
    const part = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    if (!part?.inlineData) throw new Error("Image data missing");
    const blob = new Blob([Uint8Array.from(atob(part.inlineData.data), c => c.charCodeAt(0))], {type: part.inlineData.mimeType});
    return { imageUrl: URL.createObjectURL(blob), blob };
};

