  // ЭКСПЕРТНАЯ КОРРЕКЦИЯ ПАРАМЕТРОВ
  let modelToUse = params.model;
  const isHighRes = params.resolution === Resolution.P1080;
  const durationInt = parseInt(params.duration || '5');

  // Для 1080p или длинных видео используем ТОЛЬКО Pro модель
  if (isHighRes || durationInt > 5) {
      log("DEBUG: Обнаружен запрос на 1080p/High-Dur. Принудительное использование 'veo-3.1-generate-preview' (Pro).");
      modelToUse = VeoModel.VEO;
  }

  const payload: any = {
    model: modelToUse,
    prompt: params.prompt || "High quality cinematic video",
    config: {
      numberOfVideos: 1,
      resolution: params.resolution,
      aspectRatio: params.aspectRatio,
      durationSeconds: durationInt
    }
  };

  if (params.mode === GenerationMode.FRAMES_TO_VIDEO && params.startFrame) {
      payload.image = { imageBytes: params.startFrame.base64, mimeType: params.startFrame.file.type };
      if (params.endFrame) {
          payload.config.lastFrame = { imageBytes: params.endFrame.base64, mimeType: params.endFrame.file.type };
      }
  }

  try {
    log(`STEP 1/5: Инициализация LRO операции (${modelToUse})...`);
    let operation = await ai.models.generateVideos(payload);
    log(`STEP 2/5: Операция запущена. ID: ${operation.name}`);

    const startTime = Date.now();
    const maxWaitTime = 15 * 60 * 1000; // 15 минут для 1080p

    while (!operation.done) {
      if (Date.now() - startTime > maxWaitTime) throw new Error("TIMEOUT: Рендеринг в облаке превысил 15 минут.");

      const elapsed = Math.round((Date.now() - startTime) / 1000);
      log(`STEP 3/5: Ожидание рендеринга... [${elapsed}s]`);

      await new Promise(r => setTimeout(r, 15000));
      operation = await ai.operations.getVideosOperation({ operation });
    }

    if (operation.error) {
        log(`API_ERROR: ${operation.error.message} (Code: ${operation.error.code})`);
        throw new Error(operation.error.message || "Ошибка на стороне Google API");
    }

    const videoResult = (operation.response?.generatedVideos || (operation as any).result?.generated_videos)?.[0];
    const videoUri = videoResult?.video?.uri || videoResult?.uri;

    if (!videoUri) throw new Error("API не вернуло ссылку на готовый объект.");

    // ЗАГРУЗКА И ВЕРИФИКАЦИЯ
    log(`STEP 4/5: Видео готово в облаке. URI: ${videoUri}`);

    // ПАУЗА ДЛЯ СТАБИЛИЗАЦИИ GCS (Критично для 1080p)
    const stabilizationDelay = isHighRes ? 12000 : 5000;
    log(`DEBUG: Ожидание стабилизации файла в GCS (${stabilizationDelay/1000}s)...`);
    await new Promise(r => setTimeout(r, stabilizationDelay));

    const downloadUrl = `${videoUri}${videoUri.includes('?') ? '&' : '?'}key=${apiKey}`;

    let retryCount = 0;
    while (retryCount < 4) {
        try {
            log(`STEP 5/5: Загрузка чанка... (Попытка ${retryCount + 1})`);
            const fetchResp = await fetch(downloadUrl);
            if (!fetchResp.ok) throw new Error(`HTTP ${fetchResp.status}`);

            const blob = await fetchResp.blob();
            log(`DEBUG: Загружено ${Math.round(blob.size/1024/1024 * 100)/100} MB. Проверка заголовков...`);

            const verify = await verifyVideoPlayback(blob);
            if (verify.ok) {
                log("SUCCESS: Файл прошел верификацию. Вывод на экран.");
                return {
                    objectUrl: URL.createObjectURL(blob),
                    blob,
                    uri: videoUri,
                    video: videoResult.video || videoResult
                };
            } else {
                log(`WARN: Верификация не пройдена: ${verify.error}. Ждем GCS...`);
            }
        } catch (e: any) {
            log(`WARN: Ошибка загрузки: ${e.message}`);
        }
        retryCount++;
        await new Promise(r => setTimeout(r, 5000 * retryCount));
    }

    throw new Error("Не удалось скачать валидный файл после 4-х попыток. Попробуйте 720p или уменьшите длительность.");

  } catch (error: any) {
    log(`CRITICAL: ${error.message}`, 'error');
    throw error;
  }
};

