// Fix: Update generateImage to handle imageSize and find image parts as per guidelines.
export const generateImage = async (params: GeneratePhotoParams, config: VertexConnectionConfig, onLog: any) => {
    const log = (msg: string, data?: any) => {
        if (onLog) onLog(msg, data);
    };

    const apiKey = getCleanApiKey(config.apiKey);
    const ai = new GoogleGenAI({ apiKey });

    log(`STEP 1/2: Запрос генерации (${params.model})...`);

    const response = await ai.models.generateContent({
        model: params.model,
        contents: { parts: [{ text: params.prompt }] },
        config: { 
            imageConfig: { 
                aspectRatio: params.aspectRatio,
                ...(params.model === PhotoModel.NANO_BANANA_PRO ? {
                    imageSize: params.quality === '4K' ? '4K' : params.quality === 'HD' ? '2K' : '1K'
                } : {})
            } 
        }
    });

    log("STEP 2/2: Обработка ответа...");

    // Iterate through all parts to find the image part, as per guidelines.
    const part = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    if (!part?.inlineData) throw new Error("API не вернуло данные изображения.");

    const base64Data = part.inlineData.data;
    const mimeType = part.inlineData.mimeType;

    // Manual decode implementation
    const decodeBase64 = (base64: string) => {
        const binaryString = atob(base64);
        const len = binaryString.length;
        const bytes = new Uint8Array(len);
        for (let i = 0; i < len; i++) {
            bytes[i] = binaryString.charCodeAt(i);
        }
        return bytes;
    };

    const blob = new Blob([decodeBase64(base64Data)], {type: mimeType});
    return { imageUrl: URL.createObjectURL(blob), blob };
};

