import {
  GoogleGenAI,
  Video,
  VideoGenerationReferenceImage,
  VideoGenerationReferenceType,
} from '@google/genai';
import {GenerateVideoParams, GeneratePhotoParams, GenerationMode, VertexConnectionConfig, VeoModel, PhotoModel, Resolution, AspectRatio} from '../types';

const getCleanApiKey = (overriddenKey?: string) => {
  let apiKey = overriddenKey || process.env.API_KEY || '';
  return apiKey.trim().replace(/["']/g, '');
}

// Верификация видео контейнера
const verifyVideoPlayback = async (blob: Blob): Promise<{ok: boolean; error?: string}> => {
    if (blob.size < 1024 * 100) return {ok: false, error: "Размер файла слишком мал для 1080p"};

    return new Promise((resolve) => {
        const video = document.createElement('video');
        video.preload = 'metadata';
        video.onloadedmetadata = () => {
            const d = video.duration;
            window.URL.revokeObjectURL(video.src);
            if (isNaN(d) || d <= 0) resolve({ok: false, error: "Metadata Error: Duration is 0"});
            else resolve({ok: true});
        };
        video.onerror = () => {
            const err = video.error;
            window.URL.revokeObjectURL(video.src);
            resolve({ok: false, error: `MediaError ${err?.code}: ${err?.message || 'Decode failed'}`});
        };
        video.src = window.URL.createObjectURL(blob);
    });
};

export const generateVideo = async (
  params: GenerateVideoParams,
  connectionConfig: VertexConnectionConfig,
  onLog?: (message: string, data?: any) => void
): Promise<{objectUrl: string; blob: Blob; uri: string; video: Video; isSimulation?: boolean}> => {
  const log = (msg: string, data?: any) => {
      console.log(`[VEO_DEBUG] ${msg}`, data || '');
      if (onLog) onLog(msg, data);
  };

  // Важно: берем ключ непосредственно перед вызовом
  const apiKey = getCleanApiKey(connectionConfig.apiKey);

  // ФОРСИРОВАНИЕ МОДЕЛИ ДЛЯ 1080p
  let modelToUse = params.model;
  if (params.resolution === Resolution.P1080) {
      log("QUALITY_UPGRADE: Для 1080p принудительно используем veo-3.1-generate-preview (Pro)");
      modelToUse = VeoModel.VEO;
  }

  const payload: any = {
    model: modelToUse,
    prompt: params.prompt || "Cinematic masterpiece, highly detailed",
    config: {
      numberOfVideos: 1,
      resolution: params.resolution,
      aspectRatio: params.aspectRatio,
      durationSeconds: parseInt(params.duration || '5')
    }
  };

  if (params.mode === GenerationMode.FRAMES_TO_VIDEO && params.startFrame) {
      payload.image = { imageBytes: params.startFrame.base64, mimeType: params.startFrame.file.type };
      if (params.endFrame) {
          payload.config.lastFrame = { imageBytes: params.endFrame.base64, mimeType: params.endFrame.file.type };
      }
  }

  try {
    log(`STEP 1: Инициализация LRO (Model: ${modelToUse})...`);
    // Создаем свежий инстанс для старта
    let ai = new GoogleGenAI({ apiKey });
    let operation = await ai.models.generateVideos(payload);
    log(`STEP 2: Операция создана. ID: ${operation.name}`);

    const startTime = Date.now();
    const maxWaitTime = 20 * 60 * 1000; // 20 минут для 1080p

    while (!operation.done) {
      if (Date.now() - startTime > maxWaitTime) throw new Error("TIMEOUT: Генерация в облаке заняла слишком много времени.");

      const elapsed = Math.round((Date.now() - startTime) / 1000);
      log(`STEP 3: Ожидание рендеринга... [${elapsed}s]`);

      await new Promise(r => setTimeout(r, 15000));

      try {
          // ПАТТЕРН FRESH INSTANCE ДЛЯ КАЖДОГО ПОЛЛИНГА (решает проблему 401 на 3-й секунде)
          ai = new GoogleGenAI({ apiKey: getCleanApiKey(connectionConfig.apiKey) });
          operation = await ai.operations.getVideosOperation({ operation });
      } catch (pollError: any) {
          if (pollError.message?.includes("401") || pollError.message?.includes("auth")) {
              log("AUTH_RECOVERY: Попытка восстановить сессию после ошибки 401...");
              // Ждем немного и пробуем еще раз с новым инстансом
              await new Promise(r => setTimeout(r, 5000));
              ai = new GoogleGenAI({ apiKey: getCleanApiKey(connectionConfig.apiKey) });
              operation = await ai.operations.getVideosOperation({ operation });
          } else {
              throw pollError;
          }
      }
    }

    if (operation.error) {
        log(`API_ERROR [${operation.error.code}]: ${operation.error.message}`);
        if (operation.error.code === 401) {
            throw new Error("Ошибка авторизации. Убедитесь, что выбран ПЛАТНЫЙ ключ в меню (Paid API Key).");
        }
        throw new Error(operation.error.message || "Ошибка Google API");
    }

    const videoResult = (operation.response?.generatedVideos || (operation as any).result?.generated_videos)?.[0];
    const videoUri = videoResult?.video?.uri || videoResult?.uri;

    if (!videoUri) throw new Error("API не вернуло ссылку на видео.");

    log(`STEP 4: Видео готово. URI получено.`);

    // ПАУЗА ДЛЯ GCS STABILIZATION
    const stabilizationDelay = params.resolution === Resolution.P1080 ? 15000 : 7000;
    log(`STABILIZING: Ожидание записи файла на диск (${stabilizationDelay/1000}s)...`);
    await new Promise(r => setTimeout(r, stabilizationDelay));

    const downloadUrl = `${videoUri}${videoUri.includes('?') ? '&' : '?'}key=${apiKey}`;

    let retryCount = 0;
    while (retryCount < 5) {
        try {
            log(`STEP 5: Загрузка файла... (Попытка ${retryCount + 1})`);
            const fetchResp = await fetch(downloadUrl);
            if (!fetchResp.ok) {
                if (fetchResp.status === 401) throw new Error("401_DOWNLOAD_AUTH_FAILED");
                throw new Error(`HTTP ${fetchResp.status}`);
            }

            const blob = await fetchResp.blob();
            log(`DOWNLOAD_COMPLETE: Размер ${(blob.size/1024/1024).toFixed(2)} MB. Проверка...`);

            const verify = await verifyVideoPlayback(blob);
            if (verify.ok) {
                log("SUCCESS: Видео полностью готово и проверено.");
                return {
                    objectUrl: URL.createObjectURL(blob),
                    blob,
                    uri: videoUri,
                    video: videoResult.video || videoResult
                };
            } else {
                log(`RETRY: Файл не прошел проверку (${verify.error}). Повтор...`);
            }
        } catch (e: any) {
            log(`DOWNLOAD_WARN: ${e.message}`);
        }
        retryCount++;
        await new Promise(r => setTimeout(r, 6000 * retryCount));
    }

    throw new Error("Не удалось загрузить видео. Попробуйте обновить страницу или выбрать другой API ключ.");

  } catch (error: any) {
    log(`CRITICAL: ${error.message}`, 'error');
    throw error;
  }
};

